/* 原创白话入口；正文保留教材约定，图用有限对象解释概念。 */
(() => {
  const D = (plainTitle,goal,story,terms,kind,nodes,caption,steps,boundary) => ({plainTitle,goal,story,terms:terms.map(([word,meaning,example])=>({word,meaning,example})),diagram:{kind,nodes:nodes.map(([name,detail])=>({name,detail})),caption},steps:steps.map(([title,text])=>({title,text})),boundary});
  Object.assign(window.PLAIN_BEGINNER = window.PLAIN_BEGINNER || {}, {
    'dm-proposition-connectives': D('两张证件，究竟要带几张？','把“都带、至少带一张、并非都带”分别判断清楚。','入口要求出示学生证或身份证。小陈两张都带，能不能进？数学里的“或者”通常表示至少满足一项，两项都满足也可以。我们先把两件具体事情各贴上真假标签，再用并且、或者、并非组合，就知道符号究竟在检查什么。',[['命题','能够明确判断真假的陈述，不要求一定是真的。','“今天带了学生证”是命题。'],['∧ / 合取','两件事都成立才算成立。','学生证与身份证都带。'],['∨、¬','∨ 表示至少一项成立；¬ 将整个判断的真假翻转。','两张都带的否定，是至少一张没带。']],'compare',[['两张都带','p 真，q 真'],['只带一张','恰好一真一假'],['两张都没带','p 假，q 假']],'p 代表带学生证，q 代表带身份证；相容的“或”不排除两者都真。',[['先给两件事命名','p 只代表“带了学生证”，q 只代表“带了身份证”。不论随后讨论哪个公式，同一个字母都不能偷偷换含义；真假标签对应的是固定的判断。'],['检查要求是否满足','“并且”要检查两项都真；“或者”只要检查有没有至少一项真。两张都带同时满足这两种要求，只带一张则只满足“或者”。'],['否定是找原要求失败的情形','“并非两张都带”包含只带一张，也包含都没带。否定只排除原要求，不能擅自加强成“两张都没带”；先列失败情况再写符号。']],'日常“或者”可能特指二选一；题目明确不能同时满足时，需要另外加入排除两者同真的条件。'),
    'dm-implication': D('承诺有没有违约，只看哪一种情况？','用具体承诺理解“如果 p，那么 q”。','老师承诺：“如果你交作业，我就给反馈。”交了却没反馈，确实违约；没交作业时，这句承诺本身没有规定老师一定做什么。蕴涵把这个检查压缩成真假规则：只有前面成立、后面不成立时失败。它并不自动说明两件事有因果关系。',[['p→q / 蕴涵','排除 p 真而 q 假的情形。','交作业却没反馈就是反例。'],['充分与必要','p 保证 q 时，p 是 q 的充分条件，q 是 p 的必要条件。','满足 p 就不能缺少 q。'],['逆否命题','把前后同时否定并交换，得到 ¬q→¬p。','没有反馈，按承诺可知没交作业。']],'compare',[['交了且有反馈','履约，真→真'],['交了没有反馈','违约，真→假'],['没有交作业','本承诺未被违背']],'只按给定承诺作逻辑检查；“没交”不等于强迫老师不给反馈。',[['先固定承诺的适用条件','p 是交作业，q 是有反馈。只有 p 成立，承诺才明确要求 q；不要把“如果”读成“有且只有”，原话没禁止老师给没交作业的人其他帮助。'],['找出唯一反例','交作业却没反馈同时满足 p 真、q 假，正好违反要求。只要要证明 p→q 不成立，就找这样的情形；没交作业的例子不能用来推翻这句承诺。'],['交换顺序要额外小心','从有反馈不能直接断言交了作业，那是把 q→p 当成原承诺。逆否则与原承诺等值：若 q 假，而 p 又真，必违约，所以在承诺成立时只能 p 假。']],'材料蕴涵只管理真假组合，不自动表示时间顺序、现实因果或概率上的影响。'),
    'dm-formula-truth-table': D('复杂条件，像算括号里的算式','先算最里面的判断，再逐层算整句话。','要计算“带学生证，并且带身份证或者有预约”，先弄清“或者”包住哪两项，再把结果交给外面的“并且”。这与先算括号内的加减相似。真值表不是背答案的表，而是把所有输入组合列全，让每个小判断逐步得到真假。',[['公式结构','说明哪些判断先组合、哪些是最外层操作。','p∧(q∨r) 最外面是 ∧。'],['赋值','为每个命题字母指定真或假。','p 真、q 假、r 真是一组输入。'],['真值表','列出全部输入情况，并逐列计算结果。','三个独立字母有 8 组真假情况。']],'flow',[['给字母贴标签','p 真、q 假、r 真'],['先算括号内部','q∨r 为真'],['再算最外层','p∧真 为真']],'图示计算 p∧(q∨r) 在一组赋值下的结果；整张表还需列全其他赋值。',[['先看最外层是谁','把 p∧(q∨r) 看成一棵有层次的树：外层要合并 p 与括号结果。括号里的 q∨r 是一个整体，不能因为从左向右读就改变原来的结构。'],['按固定输入算小块','这一行 q 假、r 真，“至少一个真”成立，所以 q∨r 得真。p 的标签仍是真；计算子公式不会改变原字母的输入，就像算术不会改写题给的数字。'],['合并后再换下一行','外层需要 p 与括号结果都真，所以本行整式真。随后换另一组输入重复计算；n 个独立字母共有 2 的 n 次方组，列全才能判断整个公式性质。']],'真值表输入可以独立列举是经典命题逻辑的模型安排；现实背景若有限制，应另将限制写作条件。'),
    'dm-equivalence-models': D('这一行成立，和永远成立差在哪里？','区分有一个成功输入、全部成功与两个公式逐行相同。','一把钥匙能开一扇门，与能开所有门不是同一件事。逻辑公式也一样：找到一组让它为真，只说明它可满足；检查每组都真，才叫恒真。两个公式偶然在这一组输入同真，还不足以说它们等值，必须对所有相同输入都给出相同答案。',[['可满足','至少存在一种输入让公式真。','p 在 p 真时成立。'],['恒真 / 矛盾','恒真是所有输入都真，矛盾是所有输入都假。','p∨¬p 恒真；p∧¬p 矛盾。'],['逻辑等值','同一论域与变量解释下，两公式对每组输入结果相同。','¬(p∧q) 与 ¬p∨¬q 等值。']],'compare',[['找到一个真行','足以证明可满足'],['检查所有行都真','才可证明恒真'],['逐行比较两式','都相同才叫等值']],'“一个”与“所有”是本课的核心差别；反例只需一行。',[['先确定题目在问几行','问“能不能为真”时，找到一个真行就完成任务。问“是不是永远真”时，一行成功远远不够；这两个问题所需要的证据数量和类型不同。'],['用失败的一行否定永远','要推翻恒真结论，只需展示一个假行，并说明对应字母取值。一个具体反例可推翻“所有”，但某个反例不会自动证明公式在其他行也全是假。'],['比较两式要使用相同输入','先固定 p、q 等字母，再分别计算两个公式。只要有一行结果不同，就不等值；若表中所有行都一致才成立，不能一边改变字母意义一边说结果相同。']],'“等值”不是说两个公式长得一样，也不只指某一次观测结果相同；必须保持变量含义与模型一致。'),
    'dm-normal-forms': D('复杂报名条件，可以整理成两种清单','看懂“满足一组就行”和“每条都得过”两种组织。','某活动允许“学生证与预约都有”，或者“教师证与邀请函都有”。这是几组完整方案中选一组。另一张规则写成“至少有一种证件，并且至少有一种凭据”，则是每条要求都要过。范式只是把逻辑条件整理成特定形状，整理不能改变哪些人有资格。',[['文字 / 文字式','这里指一个命题字母或它的否定。','p 与 ¬p 都是一个文字。'],['析取范式','若干“并且”小组再用“或者”连接。','(p∧q)∨(r∧s)。'],['合取范式','若干“或者”条款再用“并且”连接。','(p∨r)∧(q∨s)。']],'compare',[['若干完整方案','每组内部都要满足'],['满足任一方案','组与组之间用“或”'],['若干必须条款','每条内部可选，条间用“且”']],'两种范式是结构类型，不表示图中任意两份规则天然等值。',[['先分清方案与条款','析取范式像允许的完整套餐，吃到任一套就够；合取范式像必须通过的审查项，每项至少有一个条件通过。先读组织方式，再看 ∧ 与 ∨，就不容易把两种名字记反。'],['整理前先处理复杂联结词','有箭头时先用等值规则去掉蕴涵，再把否定推到单个字母前。每一步都应保持所有输入的结果不变，不能只看式子变短就认为化简正确。'],['按目标方向作分配','想要“或连接且组”，就向那个形状分配；想要“且连接或组”，则向另一种分配。展开可能让式子变长，它的价值是规则统一，不是保证表达最短。']],'普通范式允许不同小组缺少某些变量；主范式还要求每组含指定的全部变量，二者不能混称。'),
    'dm-principal-forms': D('按真假地图，把每个允许情况写回来','从具体真假行构造只认这一行的条件。','两枚开关 p、q 一共有四种开法。若只有“p 开、q 关”和“两枚都开”能亮灯，可以为每个允许情况写一个精确描述，再把它们用“或者”连起来。精确描述必须连没打开的开关也说清，这就是最小项从真值表恢复公式的办法。',[['最小项','每个变量恰出现一次的合取，指定一个精确真值行。','p∧¬q 只在 p 真 q 假时为真。'],['最大项','每个变量恰出现一次的析取，恰在指定一行上为假。','¬p∨q 只在 p 真 q 假时为假。'],['主范式','按固定变量集合用最小项或最大项组成的标准形式。','先约定顺序 p、q，再给各行编号。']],'flow',[['列四种开法','00、01、10、11'],['圈出亮灯行','10 与 11'],['分别写精确条件','p∧¬q，p∧q'],['把真行用或相连','(p∧¬q)∨(p∧q)']],'1 表示真、0 表示假，变量顺序固定为 p、q。',[['先统一地图坐标','把 p 放前、q 放后，00 指两者都假，10 指 p 真 q 假。换变量顺序会改变行编号，所以编号不能脱离约定独立使用；本题的真行是 10 和 11。'],['每个真行都说完整','真行 10 要 p 真、q 假，写 p∧¬q；11 写 p∧q。每一项都含全部指定变量，才能只认一个行，漏掉 q 就同时接受多个输入。'],['用或者收齐所有允许情况','只要落在任意一个真行就让灯亮，所以把两项用 ∨ 相连，其他行全不接受。若从假行构造合取主范式，则用在该行恰为假的最大项，符号选择方向不同。'],['不要用最小这个词猜数值','最小项不是数值最小，而是对一行作完整刻画。最小项在目标行真，最大项在目标行假；写完都可以代入那个输入检查，避免只凭口诀颠倒正负。']],'极端情形可能没有真行或没有假行，需要采用空析取、空合取等约定；应与教材定义保持一致。'),
    'dm-functional-completeness': D('只给一种积木，也能搭出所有真假规则吗？','用能否造出“非”和“与”理解联结词是否够用。','工具箱只有一种特殊按钮：两输入都开时输出关，其余输出开。乍看缺少“非”和“与”，但把同一输入接到按钮两端，就得到反转开关；再把按钮输出反转，就能做出“与”。只要基础操作能被重新搭出，复杂真假规则也能继续搭起来。这是完备性的构造思路。',[['布尔函数','根据若干真或假输入产生真或假输出的规则。','两个输入的与、或都是例子。'],['NAND / ↑','先取“与”再否定，也叫与非。','p↑q＝¬(p∧q)。'],['完备联结词集','仅使用这一组操作就能表示任意有限输入布尔函数。','若能搭出已知够用的非与与，便有构造路线。']],'flow',[['只有与非按钮','p↑q＝¬(p∧q)'],['同一输入接两端','p↑p＝¬p'],['再反转一次输出','得到 p∧q']],'电路连线只是二值逻辑构造，不讨论真实芯片电气条件。',[['先理解唯一按钮怎样响应','两端都真才输出假，其余输出真，这叫与非。它看起来不是普通否定，但允许把同一个输入放到两端：两端同为 p，按钮便刚好翻转 p 的真假。'],['先搭出一个基础能力','p↑p 得到 ¬p，因此工具箱已经能制造“非”。这里不是偷偷加入一个新按钮，而是用已有按钮的特定连接方式形成组合，构造证明每一步都必须可追踪。'],['再搭出另一种基础能力','先做 p↑q，再让同样的结果接到另一个与非按钮两端，就把否定再翻回来，得到 p∧q。由于非与与已可构造任意布尔函数，与非便也足够。']],'完备讨论可表示能力，不保证门数最少或运行最快；还须声明是否允许常量等构造约定。'),
    'dm-incomplete-invariants': D('只有“与”和“或”，为什么怎么搭都缺一种能力？','找到所有组合都保留的限制，证明工具箱不够用。','有一种积木规则：输入里把某些关改成开，输出绝不会从开变关。单独的“与”和“或”都这样；把它们套很多层，这个限制仍在。但“非”恰好在输入由关变开时，把输出从开变关。所以再复杂的与或组合也造不出非，不必一座一座穷举所有组合。',[['单调性','输入按 0 到 1 增大时，输出不从 1 降到 0。','与、或都单调。'],['不变量','每次合法构造都继续保留的性质。','用单调操作组成的表达式仍单调。'],['不完备','至少存在一个布尔函数无法由给定工具表示。','非不是单调函数，所以与或不够。']],'flow',[['检查每块积木','与、或都保持单调'],['检查任意拼接','单调操作复合仍单调'],['找到目标不符合','非把 0→1 变成 1→0']],'这里限只用 ∧、∨；若加入否定，结论会改变。',[['先检查最小操作','把任一个输入从假改真，其余不变，与和或都不会把原先真的输出变假。这种共同限制叫单调性，它说的是输入变化时输出允许怎样变化，而不是运行速度。'],['证明嵌套也逃不开','内层输入增大只会让内层输出不变或增大，外层同样不能因输入增大而降下去。因此任意有限层与或组合都继续单调，这一步把无穷多个可能表达式一并覆盖。'],['找一个限制之外的函数','否定在输入 0 时给 1，输入增为 1 时反降为 0，违反单调。所以它绝不可能由只含与或的公式表示。找到一个做不到的目标，就足以证明不完备。']],'只说“我试了很多式子都不行”不是证明；不变量必须先覆盖所有允许的构造，再排除目标。'),
    'dm-inference-rules': D('理由都真时，结论会不会还错？','用一个反例检查一段推理是否可靠。','有人说：“带学生证就能进馆；小陈能进馆；所以他带了学生证。”听起来顺，但小陈也可能凭教师证进去。推理是否有效，不看结论碰巧真不真，而看能否找到理由全成立、结论却失败的一种情况。先试着找这种漏洞，比背规则名更直观。',[['前提 / 结论','前提是提供的理由，结论是打算由这些理由保证的判断。','有证能进、确实有证，因此能进。'],['有效推理','不可能出现所有前提都真而结论假的情形。','p→q 与 p 保证 q。'],['反模型','让前提全真、结论假的具体解释。','能进但没有学生证，推翻反推。']],'compare',[['正确方向','有证能进＋有证→能进'],['可疑反推','有证能进＋能进→有证？'],['给出漏洞','凭教师证进，没有学生证']],'p 代表带学生证，q 代表能进馆；原规则没有禁止其他入馆途径。',[['先把理由与结论分开','不要只看句子里出现相同字词。正确形式是：已知 p→q，又确实有 p，就能得到 q。p 成立时规则保证 q，正好排除了前提真而结论假的可能。'],['把怀疑推到一组具体真假','可疑反推给出的是 q，却想得到 p。取 p 假、q 真，规则 p→q 仍真，q 前提也真，而结论 p 假。这一组真假已经足以说明推理形式不可靠。'],['回到现实造出同样漏洞','小陈用教师证进入，所以“能进”成立，“带学生证”却不成立。反例不需要说明每次都错，只说明现有理由不能保证结论；若另加只有学生证才能进，问题才改变。']],'有效不代表前提在现实一定真；它保证的是一旦前提都真，结论就不能假。'),
    'dm-proof-strategies': D('证明之前，先决定要交出哪一种证据','按结论形状选择直接、分类、条件或反证。','要证明一份作业合格，可以直接逐项检查；要证明不论天气都能到校，可以分晴天雨天；要证明“有票就能入场”，先假设有票再完成后续；若要证明不可能，也可先假设发生，推出矛盾。证明不是把学过的公式随机堆起来，而是管理当前可以使用哪些条件。',[['直接证明','从已知条件一步步推出目标。','由偶数定义写出 2k，再计算平方。'],['分类证明','把所有可能情况分完，每类都推出同一结论。','整数分奇数、偶数，不能漏类。'],['临时假设 / 反证','临时条件有使用范围；反证假设目标否定并推出矛盾。','证明不可能存在某对象，先暂设存在。']],'branches',[['看目标形状','要证明具体式、蕴涵或不存在？'],['选相应路线','直接算、分情况或暂设相反'],['收回临时假设','结论须对应已证明的范围']],'分支是证明策略，不表示任意猜一条路线就一定成功。',[['先问目标需要怎样成立','若目标是 p→q，就先在 p 为真的条件下尝试证明 q；若要说明某对象存在，就需要给出合格对象或可靠存在理由。证明形式应匹配任务，不能用一个个例代替所有对象。'],['临时借用条件时标清范围','反证可以暂时设想目标不成立，推到与已知条件矛盾。分类则要穷尽可能情况，并在每一类完成推导。未结束的分支里得到的结论，不能随手拿到别的分支使用。'],['结束后说明自己真正得到了什么','在假设 p 下证明 q，只能收束为 p→q，不能无条件宣布 q。若相反假设导致矛盾，可以撤销该假设；写清撤销与保留的条件，读者才能审核推理。']],'反证、分类等是组织方式，仍需每一步符合已知定义与规则；漂亮的形式不能补上缺失的理由。'),
    'dm-predicates-domain': D('“他是偶数”里的“他”，到底从哪挑？','先规定对象范围，再判断每个对象是否符合性质。','桌上卡片写着 1、2、3。“这个数是偶数”还留着一个空位，填 1 就假，填 2 就真。若说“所有卡片都是偶数”，需要逐张查；若说“有张卡片是偶数”，找到 2 就够。谓词表达带空位的判断，量词则说明要怎样在规定范围内选对象。',[['论域','当前允许变量取值的对象范围。','本例只有三张卡 1、2、3。'],['谓词 P(x)','留有对象空位的判断，填入后可判断真假。','P(x) 表示 x 是偶数。'],['∀ / ∃','∀ 读所有，∃ 读存在至少一个。','∀xP(x) 要全过；∃xP(x) 找一个过。']],'flow',[['先限定卡片','论域为 {1,2,3}'],['填进判断空位','偶数？假、真、假'],['按量词决定过关','全称失败，存在成功']],'变量 x 只从已声明论域选取；换论域可能改变结论。',[['不要让范围藏起来','“所有数都怎样”若未说整数、自然数还是实数，可能有歧义。先声明论域为桌上的三张卡，随后 x 才有明确候选范围；量词不会自动扩大到世界上所有东西。'],['空位填入后才得到判断','P(1) 是假，P(2) 是真，P(3) 是假。P 本身表达统一检查标准，x 是被检查的对象。不要把 P(x) 当成所有输入都同真或同假的一个固定命题。'],['所有与存在需要不同证据','∀xP(x) 因卡 1 不合格而失败；∃xP(x) 因卡 2 合格而成立。证明存在无需每张都过，否定全称也无需每张都失败，一张具体反例就够。']],'本课采用经典逻辑及明确论域；“存在”表示论域内至少一个，不暗含只有一个。'),
    'dm-quantifier-order': D('人人能挑老师，和同一老师教所有人','用先选谁、后选谁看懂量词顺序。','甲同学选张老师，乙同学选李老师，两人都找到了老师。这足以支持“每个同学都有一位老师”，却不能证明“有同一位老师教所有同学”。前一句先给定同学，老师可以随人变化；后一句必须先固定老师，再让他通过所有同学的检查。顺序决定能不能因人而选。',[['∀x∃y','先给任意 x，再允许为这个 x 找一个 y。','每个同学可以有不同老师。'],['∃y∀x','先固定某个 y，再要求所有 x 都与它符合关系。','同一位老师必须教所有同学。'],['量词否定','否定所有变成存在反例，否定存在变成全部不合格。','不是人人有老师＝有同学没有任何老师。']],'compare',[['给定甲同学','可选张老师'],['给定乙同学','可选李老师'],['要求同一个人','需另找能教甲乙的老师']],'图前两步支持 ∀同学∃老师；不能据此直接合并成 ∃老师∀同学。',[['先把选择顺序说出口','∀x∃y 的 x 先来：有人交给你任意一个同学，你再找适合他的老师。y 可以依赖 x，因此甲乙用不同老师并不违反要求；不需要提前交出一个万能老师。'],['换顺序就多了统一要求','∃y∀x 要先交出一位老师，再逐个检查每位同学是否由他教。两个同学分别有老师仍可能没有共同老师，所以不能把两个量词看成可随意交换的装饰。'],['否定也要逐层检查','“不是人人都有老师”意味着至少找到一位同学，对任何老师都不满足任教关系。先否定外层所有，再否定内层存在，得到存在同学且所有老师都不教他。']],'仅同类量词在相应规则下可交换；全称与存在互换通常会改变意思。'),
    'dm-free-bound': D('同一个字母，也可能一个受管一个自由','逐个位置找负责它的量词，而不只看字母名字。','看“对所有 x，x 都小于 y”。这里 x 从范围内逐个代入，受到前面的“所有 x”管理；y 没有负责人，仍是等待外部给值的空位。若把式子放进更大的括号，同一个 x 还可能在括号外另有一次自由出现。判断自由或约束要看每一次出现的位置，不是给整个字母永久贴标签。',[['约束变量出现','位于相应量词作用范围内、受它管理的一次变量出现。','∀x(x<y) 中的 x 受约束。'],['自由变量出现','没有被所在范围内相应量词管理的变量出现。','同式中的 y 是自由的。'],['闭式','没有自由变量出现的公式。','∀y∀x(x<y) 虽可能假，但它是闭式。']],'layers',[['先画量词括号','∀x 的范围是 x<y'],['给出现位置找主人','x 归 ∀x，y 没负责人'],['再查有没有空位','有自由 y，就不是闭式']],'“自由”不表示随意乱用，而是该公式的真假可能仍依赖外部给值。',[['范围先于字母名称','∀x 后面指定范围中的 x 由该量词管理。要逐个出现位置检查：括号结束后，外面的同名 x 不会自动继续受它管辖。因此先标范围比通篇搜索一个字母可靠。'],['保留外部还要填写的空位','x<y 中 y 没有对应量词，所以是自由出现。将 y 设为某个具体对象后，公式才确定相应意义；自由变量有点像函数等待的参数，不是公式写错的同义词。'],['闭合不等于成立','把所有自由位置用合适量词约束，可得到闭式。闭式只是不用再从外部给自由变量赋值，仍可能真也可能假；不要把语法分类误当成真假结论。']],'这里讨论的是变量在公式中的出现；同名字母在不同范围可各有含义，改名应避免捕获。'),
    'dm-translation-quantified': D('“只有一人”比“有一个人”多了什么？','把范围、存在和唯一性分成几层写。','班里有人交了作业，只需找到一个；班里恰好一人交了作业，还得保证其他交作业的人都是同一个。写公式时不要一次猜出长式子：先列选人的范围，再写这个人满足什么，最后检查有没有禁止其他人。口头的“只有”“不是所有”也要先翻成清楚的资格规则。',[['存在','论域内至少有一个对象满足条件。','有同学交作业，不排除两人。'],['唯一存在','至少有一个满足，而且任何满足者都等于它。','存在 x 交作业，所有交作业的 y 都等于 x。'],['只有 A 才 B','B 发生时必须满足 A，即 B→A。','只有有票才能进：进场→有票。']],'flow',[['先锁定对象范围','班里的同学'],['找一个合格者','x 已交作业'],['检查其他合格者','交作业的 y 必须等于 x']],'唯一性要求“所有合格者是同一人”，并不要求班里只有一个人。',[['先给每个字母一个角色','论域若包含所有人，就用学生条件限制；若已经限定为本班同学，则可直接选人。不要让“所有”误管到本来不在题意中的对象，也不要把限制条件与结论并列加强。'],['存在与唯一分开证明','先给出交作业的 x，证明不是零人；再取任意交作业的 y，证明 y＝x，排除第二个不同的人。只写有 x，缺少后半句，就只能得到至少一人。'],['把口头关键词还原成失败情形','“只有有票才进”失败于无票却进，所以进推出有票。“不是所有人交作业”失败的全称里至少有一个未交者，而不是全体都未交，先口头检验再符号化。']],'“唯一”相对于已固定条件与论域；更换范围后唯一性可能改变，不能省掉筛选条件。'),
    'dm-quantifier-equivalences': D('两件事各有人做，不代表同一个人都做了','用不同证人检查量词能否拆开。','甲会唱歌，乙会跳舞，所以有人会唱歌，也有人会跳舞。但这不能证明有人既会唱歌又会跳舞，因为甲乙可能各会一种。量词等值律不只是在挪符号，它管理两边是不是必须使用同一个对象。每次想拆存在量词，都问一句：原来那位证人是不是被偷偷换成两个人了？',[['证人','使存在判断成立的具体对象。','甲是“有人会唱歌”的证人。'],['量词分配','尝试把一个量词移入组合条件的两部分。','∀x(P∧Q) 可拆成两个全称。'],['反例','让一边真、另一边假的小模型。','甲只唱、乙只跳，两个存在真，同人兼会假。']],'compare',[['甲只会唱歌','唱真，跳假'],['乙只会跳舞','唱假，跳真'],['寻找同一证人','没人同时会两样']],'反例推翻 ∃x(P∧Q) 与 (∃xP)∧(∃xQ) 一般等值的说法。',[['先看原式是否要求同一对象','∃x(P(x)∧Q(x)) 先找一个 x，再检查两项，因此唱与跳必须属于同一人。量词作用范围是一整个括号，这个共同对象要求不能在拆式时消失。'],['拆开后可能允许各找各的','(∃xP(x))∧(∃xQ(x)) 中两次存在各管各的范围，可分别找甲乙。两边同写字母 x 并不自动要求同一人，所以这份结论比“有人两样都会”弱。'],['用小表核查正确等值律','全称对并且可拆，因为每人两项全过等于每人各项都过；存在对或者也可拆。其他方向不要按形状模仿，用甲乙两人的小模型检查常能立刻发现证人被分散。']],'某些附加条件会使特殊公式恰好等值；本课判断的是对所有模型是否成立的一般规则。'),
    'dm-substitution-capture': D('给字母改名，不能把自由的人圈进别人的队伍','分清改变量名称与改变变量受谁管理。','一张表让 x 留作外部输入，另一处写着“对所有 y”。如果直接把自由 x 换成 y，它可能突然落进“所有 y”的范围，原先等待外部给值的位置便被收编了。正确代入像改工牌：名字能换，岗位关系不能无意改变。必要时先给原先受量词管的字母换一个全新名字。',[['代入','用指定项替换公式中相应自由变量出现。','把自由 x 换成参数 y。'],['变量捕获','代入后原本自由的位置意外落入同名量词管理。','把 x 换成 y 后，被 ∀y 圈住。'],['约束变量改名','连同相应范围内受它管理的出现一起换成新名。','∀y 的那组 y 统一先改为 z。']],'flow',[['原来保留外部 x','公式 ∀y R(x,y)'],['先改内部管理名','改成 ∀z R(x,z)'],['再代入外部参数','x 换 y：∀z R(y,z)']],'R 表示两对象间的某种关系；新字母 z 必须不会造成其他冲突。',[['标清原来谁自由谁受管','∀yR(x,y) 中 x 自由、y 受量词管辖。若直接把 x 写成 y，就得 ∀yR(y,y)，外部参数消失了，意思变成检查每个对象与自己，这不是单纯替换名称。'],['先给内部角色一个新工牌','把量词及其绑定的 y 全部换为未冲突的 z，得到 ∀zR(x,z)。每次仍是固定外部 x 与所有候选对象配对，原意没有变化，这叫安全的约束变量改名。'],['代入后重新检查依赖','现在把自由 x 换成 y，得到 ∀zR(y,z)。y 保持自由，仍由外部指定；z 负责全称遍历。逐一核对出现位置，就能确认没有把参数偷偷变成量词挑选对象。']],'不是见到同名字母就整篇替换；嵌套量词可能让相同名称分别管理不同出现，必须按作用范围操作。'),
    'dm-prenex-rules': D('把选人说明搬到前面，条件得先讲清','理解前束形式，以及量词外提前要检查自由变量。','活动规则的一部分说“所有人都通过检查”，另一部分说“灯亮”。想把“所有人”提到整句话前，先要确认灯亮这件事不依赖正在挑的那个人。若另一部分恰好还用着同名自由变量，直接搬就会改变它的含义。前束范式是把量词集中在前面，不是无条件拖拽符号。',[['前束范式','所有量词集中在前部，后面的主体不再含量词。','∀x∃y R(x,y)。'],['外提条件','搬出的量词不能意外约束另一部分的自由变量。','把 ∀x 搬过 B 前，须确认 x 不在 B 自由出现。'],['否定翻转','否定全称变存在，否定存在变全称。','¬∀xP(x) 等值于 ∃x¬P(x)。']],'flow',[['整理逻辑连接','先消箭头、处理否定'],['给各量词改新名','避免不同范围重名'],['检查后逐个外提','保留选择顺序与依赖']],'本课按非空论域的经典逻辑规则整理；每一步都要使用适用的等值律。',[['先消除会影响方向的外壳','遇到否定包着量词，先用“不是所有＝存在反例”等规则翻转量词。蕴涵也可先改写成否定与或者，避免搬家时把本来应翻转的量词原样拖出去。'],['不同负责人先有不同名字','左右两部分可能各写一个 x，它们原来独立管理。先各改成不冲突的新名字，确认新名字不抢走其他自由位置，再检查外提条件，这比直接挪动容易保持原意。'],['逐步搬并复述谁先选','每外提一个量词，就说一句先给谁、后找谁。不得为了形式整齐随意交换全称与存在，也不能让外面的自由变量突然被新量词圈住；主体与依赖关系都要保持。']],'前束形式通常不唯一；不同排列是否等值取决于依赖和规则，不能凭字面相似判断。'),
    'dm-prenex-worked': D('两边都叫 x，搬到前面先给它们分名','一步步完成不抢变量的前束整理。','两张独立清单都把自己的行号叫 x，合表时若当成同一行号就会混乱。公式左右两块的量词也可能各用 x，却各自管理自己的对象。我们用“所有对象有 P 性质，并且至少一个对象有 Q 性质”做小题，先分别改名，再按规则把量词提到前面。',[['量词辖域','某量词实际管理的公式范围。','左 ∀x 只管 P(x)，右 ∃x 只管 Q(x)。'],['新鲜变量','不与当前相关自由或绑定名字冲突的新名称。','将右侧的 x 改成 y。'],['等值变换','每一步在规定模型中保持真假不变的改写。','整理前后不是只在某个例子上同真。']],'flow',[['原式有两组 x','(∀xP(x))∧(∃xQ(x))'],['右边先安全改名','(∀xP(x))∧(∃yQ(y))'],['逐步提取量词','∀x∃y(P(x)∧Q(y))']],'示例按非空论域整理；这里不同量词的变量没有交叉自由依赖。',[['先把两个独立范围隔开','原式的两个 x 由两个量词各自管理，不要求同一对象同时满足 P、Q。先在纸上圈出两个括号，明确左边检查所有对象，右边单独找一个 Q 对象。'],['改名只改对应那一组','将右边量词及其范围内受它约束的 x 改为 y，左边保持不动。得到两个不同名字后，才容易看出 x 不在右边自由出现，y 也不在左边自由出现。'],['搬家后再次口头验算','按等值规则得到 ∀x∃y(P(x)∧Q(y))。意思仍为每个 x 都有 P，且可以找到 Q 对象。这里 Q 与 x 无关；不能由这道特殊题推出任意 ∀∃ 都能交换。']],'本例只示范无交叉依赖的一种结构，复杂题要逐步核查捕获与量词顺序，不能照抄排列。'),
    'dm-quantifier-inference': D('“随便一个人”与“找到的那个人”不能混用','理解全称点名与存在证人的权限范围。','如果名单上每个人都体检合格，小陈在名单里，就可点名说他合格。但如果只知道名单里有一个合格者，你不能随手指定他就是小陈。证明所有人时也不能专挑最配合的人来演示。量词推理的限制，就是防止把一个特殊证人冒充任意对象，或把任意对象偷偷附加特殊条件。',[['全称实例化','由所有对象满足条件，推出某个合格取值也满足。','所有学生合格，则学生小陈合格。'],['存在实例化','为存在的对象引入一个未被占用的临时名字，并保持其限制。','某人合格，暂称 a，不能断言 a 是小陈。'],['全称推广','对未依赖特殊假设的任意对象证明后，才能推出所有对象。','选任意学生证明，而非特选第一名。']],'compare',[['所有人都合格','可点名任一范围内对象'],['至少一人合格','只知有证人，身份未定'],['想推出人人合格','须证明任意对象都行']],'临时证人名字不能冒充原有指定对象，结论也不能无故依赖它。',[['从所有走向某个通常容易','全称已覆盖论域每个对象，点名某个合法对象没有增加要求。例如所有学生都合格，再指定一个学生，就能得到其合格；但先要确认指定对象确实在要求范围里。'],['从存在拿到的只是匿名证人','存在只保证有人满足，暂取名字 a 方便继续推导，并不授予其他身份。若原来已谈到小陈，就不能直接把 a 改成小陈；它也可能是另一个人。'],['推回所有时要检查特殊依赖','若对 a 的证明用了“a 是第一名”等特殊前提，就不能推广全体。只有 a 真的是任意对象且没有相关未解除的特殊假设，证明才有资格代表所有候选。']],'不同证明系统对新鲜名字和假设范围有明确写法；理解证人权限之后仍需遵守教材形式规则。'),
    'dm-quantified-proof': D('同一个证人，怎样穿过两条普遍规则','把存在对象与两条全称规则接成完整证据链。','已知“每个报名者都有学号”“每个有学号者都能领卡”，又知道至少有一个报名者。要证明有人能领卡，先找出那个报名者，沿同一人的身份依次用两条规则。不能第一步谈甲、第二步换乙，最后把两个不同人的性质拼成一个人。长证明也可以拆成这样的身份连续追踪。',[['存在证人','让存在条件成立、暂时取名的对象。','选一个报名者 a。'],['全称规则点名','把对所有人的规则应用到当前同一个对象。','报名者 a 有学号，故 a 能领卡。'],['存在推广','某具体对象已满足条件，就可得至少存在一个满足者。','a 能领卡，因此有人能领卡。']],'flow',[['取一个报名者','存在证人 a'],['沿规则得到学号','同一个 a 有学号'],['再得到可领卡','同一个 a 能领卡'],['放下临时名字','因此有人能领卡']],'P 表报名、Q 表有学号、R 表能领卡；使用 P→Q 与 Q→R 的全称规则。',[['先取证人并留在假设范围','由有人报名，暂时称那个人 a。我们不知道他原来的名字，也不需要知道；只使用已保证的“a 报名”，不能再给他增加没有依据的特长或身份。'],['两次点名都用同一对象','所有报名者有学号，对 a 应用得 a 有学号；再用所有有学号者能领卡，仍对 a 应用得 a 能领卡。每一步都保持对象身份，证据链才没有断。'],['明确归结到存在结论','已经有 a 这位合格证人，便可说至少有一个人能领卡。最后结论不需要保留 a 的特殊名字，只保留它保证的存在事实；这也避免把临时证人假设越界带出。'],['再检查是否偷换了方向','若第二条只有“能领卡的人有学号”，就不能从有学号推出领卡。量词存在并不会修复命题推理的反推错误，身份追踪与箭头方向都得同时正确。']],'有报名者这一存在前提不可省；若没人报名，两条全称规则可能成立，却不能保证有人领卡。')
  });
})();
(() => {
  const D = (plainTitle,goal,story,terms,kind,nodes,caption,steps,boundary) => ({plainTitle,goal,story,terms:terms.map(([word,meaning,example])=>({word,meaning,example})),diagram:{kind,nodes:nodes.map(([name,detail])=>({name,detail})),caption},steps:steps.map(([title,text])=>({title,text})),boundary});
  Object.assign(window.PLAIN_BEGINNER = window.PLAIN_BEGINNER || {}, {
    'dm-graph-model': D('画地图时，哪些细节可以先忘掉？','选出顶点、边及方向，把现实问题转成明确模型。','研究三栋楼之间能否通行，先把楼画成点、通路画成线，就不用把树木、外墙和道路弯曲全部画出来。若研究单行道，线还要加箭头；若研究路长，则给线标数字。图是一种选择性保留信息的模型，点的位置与线的形状通常不是问题本身，先说清研究目标再决定保留什么。',[['顶点','表示研究对象的点。','楼、同学、任务都可作顶点。'],['边 / 有向边','表示对象间联系；有向边还区分起终点。','单行道路用箭头。'],['简单图与权','简单图通常无自环且同一对顶点至多一边；权是附在边上的数值。','权可表示长度，但也可能表示费用。']],'flow',[['选研究对象','三栋楼 A、B、C'],['选要保留的联系','可直接通行就连边'],['补上必要属性','单行加方向，路长加权']],'图模型依题意选择；纸上边的长短不自动等于权值。',[['先问问题是可达还是距离','只研究能否从楼A到楼C时，道路弯曲可能不重要；研究耗时则不能把所有边当一样。建模不是复制照片，而是保留足以回答目标的关系。'],['顶点和边的角色别混','同一现实对象可因问题不同扮演不同角色。公交站作点、线路相邻作边是一种方案；若要研究线路间换乘，也可能把整条线路作点，须从头说明边代表什么。'],['给模型边界做说明','道路双向才适合无向边，单向必须保留方向；两条不同道路是否合并也要看是否需要多重边。选错模型可能让后续证明很漂亮，却回答了另一个问题。']],'图不自动包含距离、几何位置或现实全部限制；建模舍弃的信息必须不影响所问结论。'),
    'dm-graph-degree': D('一条握手，为什么会在两个人账上各记一次？','按边的两个端点数出度数和。','三个人中甲乙握手，乙丙握手。甲说自己握了1次，乙2次，丙1次，加起来4，但实际握手只有2次。原因是每次握手都被两位参与者各报一次。无向图里每条边也给两端各贡献一个度，因此总度数是边数的两倍，奇数度的顶点数量也必须为偶数。',[['度数 d(v)','无向图中接在顶点v上的边端数量，自环通常贡献2。','链条甲—乙—丙的度为1、2、1。'],['握手定理','全部顶点度数之和等于2倍边数。','1+2+1=2×2。'],['奇度顶点','度数为奇数的顶点。','本例甲丙两个，数量为偶数。']],'flow',[['每边有两端','两次握手，共四个参与端'],['每人报告自己的端','甲1，乙2，丙1'],['总端数除以二','4÷2＝2条边']],'本图为无向简单链；有向图需区分入度与出度，自环采用贡献2的通常约定。',[['每条边独立记两笔','无论边在图上画多长，它连接两个端点就对总度贡献2。自环两端在同一点，也记2，而不是因为只见一个顶点就只算1。'],['把两种统计方法对齐','一边逐点数得到度数和，另一边逐边数得到2m，其中m是边数。它们统计同一批边端，所以相等；除以2是在消除每条边的双计，而不是修正重复顶点。'],['奇数项必须配成偶数个','总度数一定是偶数，偶数度项不改变奇偶性；剩下若有奇数个奇度项，总和就成奇数。故奇度顶点个数为偶数，但每个奇度值可以不同。']],'度数和只是必要的计数约束，一份整数序列和为偶数不保证能成为简单图的度数序列。'),
    'dm-graph-isomorphism': D('点换了名字，连线规则有没有换？','先用不变量排除，再用完整对应证明同构。','把三角形三个点叫甲乙丙，或叫1、2、3，边画弯一点，都没改变谁与谁相连。图同构就是能给出一一改名，让所有连接完全对应。反过来，两图点数边数相同只是初步检查，好像两班人数相同不代表朋友关系也一样；最终还得看每一对相邻与不相邻是否保持。',[['图同构','顶点之间存在保持邻接关系的双射。','三角形任意一致改名仍同构。'],['不变量','换名后不会改变的性质，可用于排除。','点数、边数、度数、连通分支数。'],['保持邻接','原来两点相连当且仅当对应两点相连。','不能只保留部分边而多出新边。']],'compare',[['第一张图','甲乙丙两两相连'],['给出改名字典','甲→1，乙→2，丙→3'],['逐对检查连线','每条边和非边都对应']],'相同画法不是必要条件；相同点数、边数和度序列也不足以一般证明同构。',[['先做便宜的排除检查','若点数不同或一图连通另一图不连通，任何改名都无济于事，可直接否定同构。度数等不变量帮助缩小候选字典，但多个检查通过不等于已经完成证明。'],['交出一个覆盖全体的字典','明确每个原点映到哪个新点，不漏、不撞。高阶点通常要对应同样度数的点，这可减少尝试；不能只说某几个点对应就省略剩下对象。'],['检验邻接的两个方向','原图任意两点有边，当且仅当像点有边，才叫结构完整保留。只检查原有边不丢失却没注意新图多边，可能把并非同构的图误判成功。']],'图若带方向、多重边或标签，保留哪些结构也须按题意加条件，不能只用无向简单图定义。'),
    'dm-graph-bipartite': D('朋友分两队，每条线都要跨队','用交替涂色理解奇环为何不可能。','给图中顶点分红蓝两队，要求每条边的两端异色。沿一条边换一次颜色，走完三角形三步又回起点时，颜色要求会与原先冲突；四边形则可以交替红蓝后回到原色。二部图就是能这样分成两队的图，没有奇数长度环正好是它的判断条件。',[['二部图','顶点可分成两个不重叠部分，每条边都跨越两部分。','同队内不能有边。'],['二染色','只用两种颜色给相邻顶点不同颜色。','红—蓝—红—蓝。'],['奇环','由奇数条边组成的环。','三角形是最小简单图奇环。']],'cycle',[['起点设红色','沿边必须换色'],['三步回到起点','要求蓝色，与原红冲突'],['四步回到起点','仍要求红色，可以一致']],'奇环意味着无法两色；完整二部性还需检查所有连通分支，不只任意一个环。',[['从一个点向外交替分组','选起点红色，邻点必须蓝，邻点的邻点再要求红。逐层推进，把每条边都检查到；图不连通时，另一个分支也要重新开始，不能漏查。'],['奇数次换色回原处矛盾','沿奇环走奇数步，颜色翻奇数次，到原点时要求与起初不同。一个点不能同时两色，因此含奇环的图绝不二部；这是局部反例就能否定全图的性质。'],['没有奇环才能始终协调','若涂色冲突，可由两条到冲突点的路径拼出奇环；反过来无奇环保证交替分组可行。图中没有三角形还不够，因为五边环也是奇环。']],'允许自环的图会立刻违反二部性；这里用简单无向图讲基本定理，方向图另需说明忽略方向方式。'),
    'dm-graph-connectivity': D('能走到，和一路不重复，是不同要求','区分允许重复的走法、边不重复与点不重复。','从甲经乙到丙，可以沿路再返回乙。若只问能不能到达，重复通常无妨；若要求每条路最多走一次，或每个点最多经过一次，限制就不同。图论把这些走法分门别类，是为防止同一句“路径”偷偷换规则。连通只关心任意两点能否找到连接路线，不要求一步直达。',[['走法 / Walk','相邻顶点与边连续衔接的序列，通常允许重复。','甲—乙—丙—乙。'],['迹与简单路径','迹不重复边；简单路径不重复顶点，中文名称以教材为准。','甲—乙—丙 是简单路径。'],['连通分支','彼此可达且不能再扩大的顶点组。','两团之间完全无路便为不同分支。']],'flow',[['先问能否到达','甲经乙能到丙'],['再加重复限制','重复边？重复点？'],['按可达关系分组','互可达一团为分支']],'无向图下基本可达对称；环、回路和迹的中文词汇需与教材定义对齐。',[['把路线逐项写出来','写出甲、乙、丙、乙，每相邻一对都有对应边，才是合法走法。它重复乙，也可能重复某条边；不先记录序列就容易只看画出的曲线猜是否重复。'],['按题目要求逐层筛选','要求不重复边便检查边身份，要求不重复点便检查顶点身份。每个点一次与每条边一次不等价，后面哈密顿与欧拉问题正是关注不同对象。'],['连通只问路线存不存在','甲与丙没有直接边，但甲—乙—丙 已足够证明两者可达。把所有互可达者收到同一最大组，得到连通分支；单个孤立点本身也是一个分支。']],'不同教材对“通路、路径、回路”用词有差异，判断时优先读重复限制，不只凭中文名字。'),
    'dm-graph-directed-connected': D('单行道能过去，未必还能回来','区分双向可达与忽略方向后的连接。','三站单行道甲→乙→丙，忽略箭头看是一整条链，所以弱连通；但丙回不了甲，不是强连通。若再加丙→甲，三站都能沿方向互相到达，才强连通。强连通分量把这样的互达站点收成一团，压成一团后能更清楚地看出团与团之间的单向依赖。',[['强连通','任意两点都能按方向分别到达对方。','甲→乙→丙→甲。'],['弱连通','忽略所有箭头方向后，底层无向图连通。','单向链也弱连通。'],['强连通分量','按方向互相可达的最大顶点组。','同团内部均能相互抵达。']],'compare',[['单向链甲→乙→丙','弱连通，不强连通'],['再加丙→甲','形成双向可达整团'],['把互达者压成团','团之间只剩单向依赖']],'“双向可达”允许经过多段不同路线，不要求每条箭头都有直接反向边。',[['尊重箭头方向试着返回','甲到丙可以先乙再丙，丙到甲却没有路线。只检查起点能到别人不足以证明强连通，因为定义对每对顺序都提出要求。'],['忽略方向是另一个问题','把甲乙丙之间箭头换成普通线，能连成一片，所以弱连通。弱与强检查的图信息不同，不应因为纸上点都挨着就宣称“明显连通”。'],['用最大互达组整理依赖','强连通分量内每个人都可达每个人；若两个分量还能双向可达，就应合并，矛盾于最大性。因此压缩后的分量图不会形成有向环，便于理解依赖顺序。']],'有的教材另定义单向连通等中间概念；不要把它与强连通或弱连通合并，按具体定义逐对检查。'),
    'dm-graph-cuts': D('拔掉这条线，大家会不会失联？','用连通分支数量变化识别桥与割点。','甲—乙—丙是一条链，删除甲乙这条边，甲就与另一边失联，所以它是桥；删除中间乙，甲丙分开，所以乙是割点。若三人还围成三角形，删一条边仍可绕路，不是桥。关键看删除后连通分支是否增多，而不是看边画在图的中间还是外面。',[['桥','删去该边后连通分支数增加的边。','链的任意一条边。'],['割点','删去该顶点及相连边后，连通分支数增加的顶点。','三点链的中间点。'],['环上边非桥','环提供另一条绕行路线。','三角形删一边仍连通。']],'compare',[['链上删除一条边','甲被隔开，分支增加'],['三角形删除一边','仍能绕行，分支不增'],['链上删除中间点','甲丙断开，乙是割点']],'割点定义是删点前后分支数比较；删去孤立点反而减少分支，不叫割点。',[['先数删除前有几团','原图不一定连通，因此不能把“删后仍不连通”当充分证据。先记录原分支数，再看变化；判断桥与割点都是比较，而不是单看删除后的绝对状态。'],['删边时只去掉那条线','链上断一条没有备用路，分支增加。环上删边可沿环其余部分绕过去，所以不是桥；这说明桥的判定依赖全图路径，不依赖线在画面的位置。'],['删点须同时拿掉相关边','移除乙也移除所有接到乙的边，再统计剩余对象的分支。端点被删除可能只留下一个连通块，不是割点；画图时若忘记删相关边，计数会失真。']],'本课按普通无向图说明；多重边会提供平行绕路，有向图的强桥等需另用定义。'),
    'dm-graph-matrices': D('表格一格，是一条边，还是一条走法？','先读行列含义，再理解矩阵乘法的中转求和。','图中甲连乙，乙连丙。邻接表格在甲行乙列和乙行丙列记1。把表与自己相乘，甲行丙列会统计“甲经哪个中间点再到丙”，此处经乙有一条两步走法。矩阵幂统计的是按长度的走法条数，不自动禁止重复顶点，所以不能把它直接读成简单路径数量。',[['邻接矩阵 A','行列同为顶点，一格记录对应两点之间的边信息。','简单图有边填1，无边填0。'],['关联矩阵','一边索引顶点、另一边索引边，记录谁接在哪条边上。','无向简单图一列通常有两个1。'],['Aᵏ','邻接矩阵的k次乘积，在相应约定下统计长k的走法。','A²甲丙项为两步走法数。']],'flow',[['写出一步联系','甲→乙，乙→丙'],['按中间点相乘求和','甲→乙→丙'],['得到两步计数','A² 的甲丙项为1']],'图用有向三点链简化；普通矩阵乘法统计条数，布尔乘法可表达是否存在。',[['先确认每一行列代表什么','邻接矩阵两边都用同一顶点顺序；关联矩阵一边顶点一边边，形状与用途不同。若顶点换顺序，相应行列必须一致改动，不能只改其中一边。'],['乘法每一项都对应一个中转','A²中的甲丙项，要对每个候选中间点求“甲到中点的边数×中点到丙的边数”，然后加起来。只有能接上的两段才贡献，正好与两步走法一一对应。'],['条数不等于可达也不等于简单路','正整数说明存在这种长度的走法，但可能重复点边。可达通常允许不同长度；若仅做真假关系复合则用布尔运算。三个问题的数字解释不同，不能混读。']],'自环、多重边与有向图改变矩阵定义细节；A⁰表示单位矩阵，对应零步原地走法，仍需跟教材约定。'),
    'dm-graph-euler': D('每条路只走一次，哪些点可以当起终点？','用进一次要出一次的配对解释奇度判据。','邮差想把图中每条路走一次。对中途经过的路口，每次进去都得再出去，边端应两两配对；只有起点可以多一条出去，终点可以多一条进来。所以若起终点不同，恰有两个奇度点；若走回原点，所有度都应偶。还得确保所有有边区域连在一起，否则再漂亮的奇偶也没法跨空白。',[['欧拉迹','每条边恰走一次的迹，顶点可以重复。','任务对象是边，不是点。'],['欧拉回路','走完全部边且回到起点的欧拉迹。','每个顶点度为偶的连通情形。'],['无向判据','非孤立部分连通且奇度点为0或2，分别对应闭合或开放情形。','有孤立点不影响走完现有边。']],'flow',[['中间点进出配对','每次两条边端'],['起终点可各落单','开放路线有两个奇度点'],['所有道路须成一片','再结合连通性判断']],'本课为有限无向图含边情形，忽略孤立顶点后的部分需要连通。',[['先确认要求是每边一次','可以多次经过同一个路口，只要不重复边；这与哈密顿的每点一次不同。若把经过过的顶点全部禁止，会错把很多合法欧拉路线排除。'],['用进出边端解释奇偶','非起终点每来一次便要离开一次，用掉偶数条边端。开放路线起终点各有一个无法配对的边端，因此二者奇度；闭合路线则起点也配对完。'],['必要条件还要配合连通','两个分开的三角形全是偶度，却无法一笔走完两团的全部边。去掉孤立点后必须连通。符合判据时可逐步拼接回路构造路线，判据不只凭奇偶单独成立。']],'有向欧拉问题要改查入度出度与可达条件，不能直接套无向奇度公式。'),
    'dm-graph-hamilton': D('每个城市只到一次，比每条路一次难在哪里？','分清哈密顿任务及充分条件与必要条件。','旅行想每个城市访问一次再回出发地，这次关注城市，不要求把所有道路走遍。一个路口有很多道路，也不能保证它们拼得出贯穿全城的圈。哈密顿回路没有像无向欧拉那样仅凭奇度点就解决的通用简单判据。学到度数定理时，必须标明它只是保证存在的一种充分条件。',[['哈密顿路径 / 回路','经过每个顶点恰一次的路径；回路另回起点。','允许有很多道路完全不使用。'],['必要条件','若存在目标就必须满足，满足它未必足够。','有回路的至少3点图中每点度至少2。'],['Dirac充分条件','n≥3的简单图若最小度至少n/2，则有哈密顿回路。','不满足此界不表示一定没有回路。']],'compare',[['欧拉看边','每条边一次，点可重复'],['哈密顿看点','每个点一次，边可不用'],['度数条件看方向','充分可保证，失败不排除']],'本课定理只用于有限简单无向图且顶点数n≥3；回路首尾同一点的记号不算重复访问别的点。',[['先圈出被禁止重复的对象','哈密顿任务要求每个城市一次，所以路线不能为了走更多边反复经过同一个点。与欧拉不同，没走到某条边并非失败，少一个顶点才失败。'],['必要性可以靠删除或度数排除','在至少3点的简单图里，回路每到一个点需要两条关联边，所以度1点排除回路。满足度至少2仍未必能绕全体，因此这个条件只是必要，不是结论开关。'],['充分定理只提供有把握的成功区','最小度达到n/2时，Dirac定理保证回路；若不达，只能说该定理无法判定。比如较长的简单环每点度2，仍有自身这条哈密顿回路，所以不能反用充分条件。']],'图论中的“当且仅当”才允许双向；使用充分定理时切勿把条件未满足当作不存在的证明。'),
    'dm-graph-tree': D('刚好连通，少一条就断，多一条就绕圈','通过三点小图理解树的等价特征。','甲—乙—丙连成一条，没有圈，任意两点之间恰有一条简单路径。删任意一条就断，加甲丙边就成圈。这种连得刚刚好的无向图叫树。n个点的树恰有n−1条边，但只有边数对了不够，还得结合连通或无环等条件，不能只看到数字就判树。',[['树','连通且无环的无向图。','三点链是一棵树。'],['叶子','树中度为1的顶点，单点树另按约定处理。','三点链的甲与丙。'],['唯一路径','树中每对不同顶点之间恰有一条简单路径。','若两条不同简单路径，会形成环。']],'flow',[['三点两边相连','甲—乙—丙，无环'],['删去其中一边','连通被破坏'],['增加甲丙边','出现一个环']],'本例简单无向图；n−1边单独不足以判定，须结合连通等条件。',[['连通保证能到，无环保证不绕','任意两点至少有一条路来自连通；若有两条不同简单路，可合成一个环，与无环冲突。于是树的路线唯一，也解释为什么每条边都关键。'],['删叶子看出边数递推','至少两点的有限树有叶子，删一个叶子及其唯一边，剩下仍是树。每少一点少一边，最终到单点零边，因此原来n点为n−1边。'],['等价判别需要把条件凑齐','n点连通且n−1边可判树，n点无环且n−1边也可判。只给边数时可能一部分成环另一部分孤立，故不能省去另一半；“刚刚好”同时依赖结构与数量。']],'空图、单点树和多重边的约定以教材为准；常用树定理一般在有限无向图背景中使用。'),
    'dm-graph-spanning': D('让所有站点连起来，最短总线长不等于从起点最近','分清生成树、最小生成树与最短路径树。','三站A、B、C间线路费用分别AB=2、BC=2、AC=3。要连通全部站，选AB与BC总费4，优于AB与AC总费5，所以前者是最小生成树；但从A到C绕B花4，反而不如直连花3。省全网总费用与让每站到A的路最短是两个优化目标。',[['生成树','保留原图全体顶点，并用原边组成的一棵树。','三站选两条边连通。'],['最小生成树 MST','在全部生成树中，总边权最小的树。','AB和BC总权4。'],['最短路径树','相对指定源点，使到每点树上路径保持最短距离的树。','从A看AC直连3更短。']],'compare',[['原图三条线路','AB=2，BC=2，AC=3'],['总费用最省方案','选AB与BC，总权4'],['从A到C最快方案','需AC=3，不是绕行4']],'图边权表示同一种成本且无向；MST优化总边权，不指定源点。',[['先确认必须覆盖全部顶点','生成树不能为省钱丢掉C，也不能用原图不存在的边。连通并无环意味着n点用n−1边；在这个候选范围里才比较权重，不能任取最轻几条而不管是否断开。'],['把所有保留边的权相加','AB与BC为4，AB与AC或BC与AC都为5，所以前者总权最小。这是全网建设总量，不是从A出发每条路线的距离，没必要先选一个根。'],['安全选边需要结构理由','Kruskal等算法按规则挑轻边并避免成环；背后可用割上的最轻安全边与交换论证说明可扩成最优。不能把“每次挑眼前最短”无条件套到所有路径问题。']],'最小生成树可能不唯一；同权安全选择可导致不同树，但最优总权相同，最短路径树则依赖源点。'),
    'dm-graph-rooted': D('给树挑个根，就有上下级；叶子还可以当密码','理解父子层次及前缀码为何能确定分界。','一棵无向树选A作根后，每个非根节点的唯一上行邻点成了父节点，层次来自距根几条边。再把二叉分支标0和1，叶子分配码字0、10、11，就能沿位走到叶子立即认出一个符号。若一个码字是另一个开头，比如0与01，就会使看到0时不知道该停还是继续。',[['根树','指定一个根后按到根的路径组织层次的树。','父节点为靠根的相邻点。'],['有序树','同一父节点的孩子还有固定先后次序的树。','二叉树左右位置不能随意交换。'],['前缀码','任何码字都不是另一个不同码字的开头。','0、10、11 可沿树叶即时解码。']],'branches',[['根开始读一位','0向左，1向右'],['左叶表示第一个符号','码字0，立即结束'],['右侧再分两个叶','码字10与11']],'代码分配到叶子；“前缀”指一个完整码字是否为另一个完整码字的开头。',[['树的根是额外选择','无向骨架不自带谁是父亲，选根后才按唯一路径确定父子。换根可能改变层次，但没改变原来的连边；兄弟的左右顺序也不是仅靠无向结构自动给出。'],['把一个符号安排到一片叶子','从根出发按0与1沿边走，得到叶子的根到叶路线就是码字。叶子不再有后续孩子，所以一个码字不会继续成为另一个叶子路线的开头。'],['读到叶子就能安全重新开始','位串01011先读0到叶，识别一个符号，再从根读10，最后11。因为无前缀冲突，每个叶子都能立刻定界；这说明结构保证的是可即时解码，不等于所有可唯一解码码都必须前缀。']],'编码例子只讨论二进制前缀性质，不声明0、10、11在任何频率分布下都最省平均长度。'),
    'dm-graph-planar-euler': D('道路不交叉地画出来，外面那一片也算一块','从树加边理解平面图的点边面计数。','把三角形画在纸上，有里面一块和外面无限延伸一块，共两个面。三个点、三条边于是满足3−3＋2＝2。一般有限连通平面图都满足这条公式。可平面性说能找到一种无交叉画法，不是眼前随手画出交叉就失败；面数则对应已经选定的平面嵌入。',[['可平面图','存在边只在共同端点相交的平面画法的图。','四边形加一条对角线可无交叉画出。'],['面','平面画法将平面分开的区域，包括外部区域。','三角形有内外两个面。'],['欧拉公式','连通平面图满足n−m+f=2。','n点、m边、f面。']],'flow',[['先从树开始','m=n−1，只有外面一面'],['在面内加一条边','m加1，面数也加1'],['关系始终不变','n−m+f=2']],'公式图解假定连通且已无交叉嵌入；不连通需使用修正公式。',[['先分清抽象图与当前画法','某两条线画成交叉，也许重画就能消掉，所以不能仅据一张交叉图证明不可平面。平面图则指具体的无交叉嵌入，面是这份画法中的区域。'],['树的外面也提供一个面','树没有封闭圈，只留下整个连通外部区域一面。代入m=n−1、f=1，得n−(n−1)+1=2。这是公式的基础，不应忘记外面而填f=0。'],['加边分面解释不变量','在保持平面嵌入的情况下加一条形成圈的边，会把一个面分成两个，边数与面数同步加1，所以n−m+f不变。由生成树逐边恢复可建立一般连通情形。']],'对不连通图，若分支数为c，公式改为n−m+f=1+c；不得把连通前提省略。'),
    'dm-graph-planar-obstructions': D('边多到挤不进去，怎样严格证明？','把平面边数上界作为必要限制，并正确使用其逆否。','K5让五个点两两相连，共10条边；若是简单平面图，五点最多允许3×5−6＝9条，矛盾，所以不可平面。K3,3虽只有9边，通过一般界还不矛盾，但它无三角形，可用更严的2n−4界得最多8边，再次矛盾。通过数量检查却不代表一定能画出来。',[['K₅','五个顶点两两连边的完全图。','有5点、10边。'],['K₃,₃','两组各3点，组间全部相连、组内无边的完全二部图。','有6点、9边，没有奇环。'],['平面边数界','简单平面图n≥3有m≤3n−6；无三角形时可用m≤2n−4。','必要条件被违反可排除平面。']],'compare',[['检查 K5','10边超过9，排除'],['检查 K3,3','9边超过无三角界8'],['普通图通过上界','仍不能保证可平面']],'边数界依赖简单图、n≥3等条件；本图用它证明两个指定图不可平面。',[['先数对点数边数并核前提','K5的边数为5×4÷2=10。若它可平面，简单平面图必要界要求m≤9，与实际矛盾，所以可反证它不可平面；是先假定可平面，再推出不可能。'],['一般界不够时使用更多结构','K3,3有6点9边，一般界只要求不超过12，不能排除。但二部图无三角形，可用更严的2×6−4=8，实际9超出，因此仍不可平面。'],['上界检查通过不是成功证书','某图边数少于上界，只说明这一种计数反证没奏效。还可能有K5或K3,3的细分等更深障碍，需其他论证；不能把必要条件反过来当充分条件。']],'含自环或多重边时不能直接套简单图边数界；三角形条件与顶点数下限也必须核对。')
  });
})();
(() => {
  const D = (plainTitle,goal,story,terms,kind,nodes,caption,steps,boundary) => ({plainTitle,goal,story,terms:terms.map(([word,meaning,example])=>({word,meaning,example})),diagram:{kind,nodes:nodes.map(([name,detail])=>({name,detail})),caption},steps:steps.map(([title,text])=>({title,text})),boundary});
  Object.assign(window.PLAIN_BEGINNER = window.PLAIN_BEGINNER || {}, {
    'dm-binary-operation': D('两张卡合成一张，结果还在盒里吗？','先固定材料集合，再检查二元运算是否封闭。','盒里只有卡 0 和 1。若规则是普通相加，1 与 1 得到 2，但盒里没有 2，规则就没有在这盒材料内部完整工作。若改成相加后除以 2 取余数，1 与 1 得 0，就一直留在盒内。“二元运算”先规定两份输入来自哪里、每对输入唯一产生什么，再讨论其他规律。',[['二元运算','把集合里的两个输入唯一变成同集合一个输出的规则。','每对卡都要能算出一个合法结果。'],['封闭','运算结果不跑出指定集合。','{0,1} 对模2加法封闭，对普通加法不封闭。'],['运算表','用行列列出所有输入组合及结果。','行1列1在模2加法表中填0。']],'flow',[['材料只许 0 和 1','输入来自同一集合'],['普通相加有漏洞','1＋1＝2，跑出盒子'],['改用模 2 相加','1⊕1＝0，结果仍合法']],'⊕ 在本课表示两数相加后除以 2 取余，不代表所有教材中相同符号都如此。',[['先问输入输出的范围','说“加法是运算”还不完整，需要指明在哪个集合上。整数加法与正整数减法面对的封闭问题不同；材料范围不是可有可无的背景，而是定义的一部分。'],['一对反例就能否定封闭','在 {0,1} 里选 1、1，普通相加得到 2。虽然其他三组输入都没出问题，这一组也足以说明普通加法不能构成这个集合上的内部二元运算。'],['换规则后重新逐对检查','模2加法把和化成余数，四组结果都为0或1。这个新规则与普通加法不同，不能证明一个规则封闭后，就顺带认为它具有交换、结合或逆元，须继续分别检查。']],'教材也可能先把外部二元函数称作运算再单独检查封闭；这里按内部运算定义讲解，做题跟随教材约定。'),
    'dm-operation-laws': D('换位置、换括号、展开，是三种不同许可','分别检查交换、结合与分配，不能混着使用。','算 2＋3 与 3＋2 是换输入位置；算 (2＋3)＋4 与 2＋(3＋4) 是换先组合哪一对；算 2×(3＋4) 与 2×3＋2×4 是两种运算配合。三个式子长得都像“换写法”，却各需不同规则。熟悉整数加法容易让人误以为所有新运算都能这么做。',[['交换律','两个输入调换位置，结果不变。','a*b＝b*a。'],['结合律','三个输入保持顺序，只改括号，结果不变。','(a*b)*c＝a*(b*c)。'],['分配律','一种运算可以按规定对另一种展开。','a×(b+c)＝a×b+a×c。']],'compare',[['换左右位置','2＋3 与 3＋2'],['只换先后组合','(2＋3)＋4 与 2＋(3＋4)'],['两种运算配合','2×(3＋4) 与 2×3＋2×4']],'星号 * 仅表示待研究运算，不能自动当成普通乘法。',[['先认出改了什么','若 a、b 的次序交换，就是在使用交换律；若顺序完全没动，只改括号，就是结合律。看到式子相等之前先指出使用的许可，能防止把一个条件当成所有条件。'],['用减法看出熟悉规则也会失效','5−2 与2−5不同，说明减法不交换；(5−2)−1为2，5−(2−1)为4，又说明不结合。否定某条规律只需找一个合法反例，不能因几个成功例子就断言成立。'],['分配要明确两种运算角色','乘法对加法分配，是 × 与＋ 两套规则的关系，不只关于一个运算。左右分配在一般结构中也要分别说明；不能把“加法对乘法也分配”当成自动对称结论。']],'所有规律都要求对指定集合中全部合法输入成立；计算一次相等只能检验例子，不能完成普遍证明。'),
    'dm-identity-absorber': D('一张不改变你的卡，与一张把你吞掉的卡','把单位元与零元当作功能，而不是数字名。','普通乘法中，乘 1 仍是自己，所以 1 像不做事的卡；乘 0 都变 0，所以 0 像吸收一切的卡。但换成加法，0 反而是那个不改变人的角色。单位元、零元是描述操作效果的名字，不是说看到数字 0 就永远扮演同一个角色。',[['单位元 e','放在任意元素左右运算，都保持该元素不变。','乘法的1，加法的0。'],['零元 / 吸收元 z','与任意元素运算都得到它自身。','乘法中 0×a＝a×0＝0。'],['左与右条件','一般运算未必交换，所以左右效果需分别检查。','e*a＝a 不能自动推出 a*e＝a。']],'compare',[['乘法遇到 1','a×1＝1×a＝a'],['乘法遇到 0','a×0＝0×a＝0'],['加法遇到 0','a＋0＝0＋a＝a']],'单位与吸收是相对于指定运算的角色；同一数字可在不同运算下换角色。',[['不改变你才叫单位','对集合里每个 a，e 放左边、放右边都得到 a，才是双侧单位元。不是找到一个恰好算完不变的例子就够，也不是非要单位元等于数字1。'],['结果总变成它才叫吸收','若 z 与任意元素组合都得到 z，它是吸收元。乘法的0符合；普通整数加法没有这样的吸收元素，因为任何固定 z 加1都会改变，故不能从加法有0便猜有零元。'],['换运算就重新认角色','加法中的0是单位元，不是“把所有人变0”的吸收元。抽象题只给运算表时，可以找保持行列的元素与恒定行列的元素，用功能判断而不是看名称。']],'有的教材对零元采用特定术语，先看它要求不变还是吸收；左右单位元也可能需单独讨论。'),
    'dm-inverse-cancellation': D('能撤回，和看起来能约掉，不是一回事','检查逆元相对于哪个单位，并识别消去失败的例子。','做完一个动作再做反向动作，可以回到不动状态，这叫有逆元。普通非零实数乘法可用倒数撤回，但模6乘法中2就做不到：乘任何余数都不可能得到单位1。甚至2×1与2×4除以6取余都为2，左边同乘2却不能把2直接约掉。',[['逆元','与原元素左右组合都得到单位元的元素。','加法中3的逆元是−3，单位是0。'],['消去律','a*b＝a*c 能推出 b＝c 等相应方向的规则。','并非所有运算都允许约掉a。'],['幂等元','与自己运算仍得到自己的元素。','集合并满足 A∪A＝A。']],'compare',[['模 6 乘法两算式','2×1≡2，2×4≡2'],['相同左因子','左边都是乘2'],['不能随意消去','1 与4并不相同']],'≡ 表除以 6 余数相同；对象为余数0到5，运算为相乘后取余。',[['先找单位再谈撤销','逆元要把原元素带回某个已规定单位。加法以0为单位，乘法通常以1为单位，因此负数与倒数不是同一种撤销方式。未说运算就问逆元，信息不完整。'],['用完整输入检查能否约掉','模6里2乘1与2乘4的结果都为2，输出相同但输入不同。因此乘2会丢信息，不能消去；这也是2在此乘法中没有逆元的直观原因。'],['重复不变是另一种性质','A 与自身求并仍为 A，叫幂等，不是在撤销之前的动作。逆元、消去和幂等各有定义；有单位不代表每个元素有逆元，有几个可约例子也不代表普遍消去成立。']],'有逆元并结合时可推导相应消去；没有这些条件不能照搬普通数的除法，零因子环境尤其要谨慎。'),
    'dm-algebraic-systems': D('给同一套材料，逐步增加能做的事情','沿结合、单位、逆元理解半群、独异点和群。','把集合与运算装成工具箱，再逐项检查它有多少能力。正整数相加可连续组合；加入0后多了一个不改变结果的单位；再加入负整数，任何一步加法都能用相反数撤回。半群、独异点、群这些名字，就是给不同能力配置取名，不是三种神秘的新数字。',[['半群','集合上的运算满足结合律。','正整数加法是例子。'],['独异点 / 幺半群','半群再具有单位元。','含0自然数加法，单位为0。'],['群','幺半群中每个元素都有逆元。','整数加法中a可用−a撤回。']],'layers',[['可以改括号组合','半群：结合'],['多一张不动卡','幺半群：再有单位'],['每张卡均能撤回','群：再有逆元']],'此路线先采用整数相关的加法实例；封闭性是集合上内部运算的前提。',[['先把集合和运算一起报出','同一集合换运算可能得到完全不同结构。正整数加法保持正整数并满足结合律，所以是半群；不因日常常用加号，就自动拥有集合外的0或负数。'],['单位必须真的在材料里','正整数不含0，因此不能拿0当其加法单位。扩展到含0自然数后，0合法且加它不变，于是得到幺半群。结构条件不仅是算式，还包括所需元素是否存在于集合。'],['逆元要对每一个元素都具备','自然数中的1没有自然数相反数，故还不是加法群；扩展到整数，每个a都有−a，便成为群。只找到少数元素可撤回，不足以给整个系统升级。']],'“自然数”是否包含0须先说明；此处明确说含0，避免因教材约定不同产生结构误判。'),
    'dm-group-definition': D('四格转盘，每一步都能继续也能退回','用模4加法亲手检查群的四项条件。','转盘只有0、1、2、3四个位置，向前走若超过3就绕回0。把“向前走几格”组合，相当于相加后除以4取余。先走3再走2等于走1；走0是不动；走1可用走3撤回。群就是让这些组合与撤销能力始终可靠的一套规则，不要求元素一定是普通数字。',[['封闭与结合','组合后仍是合法元素，分批组合不改变总效果。','3⊕2＝1，括号可改变。'],['单位元','组合后不改变动作效果的元素。','走0格。'],['逆元','能把动作组合回单位的元素。','走1与走3合起来走0。']],'cycle',[['四个位置循环','0→1→2→3→0'],['允许连续组合','3⊕2＝1'],['找到不动与撤回','单位0，1的逆为3']],'⊕ 表模4加法；循环图表示反复加1，不是把群定义成任何一张环图。',[['所有组合都留在四格内','先算普通和，再取除以4的余数，所以输出必在0到3。连续几次移动只取决于总步数的余数，先合并前两步还是后两步不会改变效果，这体现结合。'],['不动动作也要是合法元素','0就在集合里，对任意a都有a⊕0＝0⊕a＝a，所以是单位。它的角色是不改变其他动作，并不是这里有个会把任何输入吞成0的吸收元。'],['逐个确认能回到不动','0的逆是0，1的逆是3，2的逆是2，3的逆是1。每一个元素都有合法撤回方式，才满足群条件。普通乘法或换一个集合后，应重新检查，不能沿用本例结论。']],'群不要求交换律，模4加法只是交换群实例；用它入门不能推断所有动作都能交换次序。'),
    'dm-group-equations': D('撤销动作，得在正确的一侧接上','在不保证交换时求解左右方程。','先穿袜子再穿鞋，撤销时应先脱鞋再脱袜子。群里解方程也要尊重顺序：若 a 与 x 组合等于 b，想去掉左边 a，就在两边左侧接 a 的逆。虽然加法例子常能自由换位置，一般群不允许，这正是要写清乘在哪一侧的原因。',[['a⁻¹','a 的逆元，使 a⁻¹a 与 aa⁻¹ 都等于单位。','它表示撤销，不必是数值倒数。'],['左、右群方程','未知量的位置不同，撤销应在相应一侧。','ax=b 得 x=a⁻¹b；xa=b 得 x=ba⁻¹。'],['乘积逆元','撤销一串操作要逆序逐个撤销。','(ab)⁻¹=b⁻¹a⁻¹。']],'flow',[['原来左侧有 a','ax＝b'],['两边左乘逆元','a⁻¹(ax)＝a⁻¹b'],['单位不改变 x','x＝a⁻¹b']],'并置表示群运算；图使用结合律，完全没有使用交换律。',[['先圈出未知量旁边的已知动作','方程 ax=b 中a在x左侧，所以选从左侧接a的逆。不要直接把a像普通数除法一样划掉；一般群只有逆元和结合的许可，未承诺可任意交换。'],['两边做同一操作保持等式','左乘a⁻¹，得a⁻¹(ax)=a⁻¹b。用结合律将左边改成(a⁻¹a)x，再用逆元得到ex，其中e为单位。每一步使用的规则都明确可查。'],['最后去掉不动动作并验算','ex=x，得x=a⁻¹b，代回a(a⁻¹b)=b可核对。若原式是xa=b则要右乘；撤销ab时也先撤b再撤a，顺序不可凭加法习惯倒换。']],'日常穿脱动作并不真构成全体可组合的群；类比只帮助记住逆序撤销，一般群方程仍按公理推导。'),
    'dm-subgroup-definition': D('从大工具箱挑一小套，还能完整工作吗？','检验小集合在原运算下是否仍有单位、组合与撤销。','模6加法有0到5六张卡，挑出0与3。两张3合成0，加0不变，而且3自己能撤回自己，所以这小套仍能完成群的操作，叫子群。若挑0与2，2加2会得到4，已经跑出小套，便不行。关键不是大小变小，而是保留原运算后能力是否完整。',[['子群','大群的一个子集合，使用同一运算时本身仍为群。','模6加法的{0,3}。'],['封闭与逆元','小集合组合与撤回都不能跑出去。','3＋3余6得0，3的逆仍为3。'],['子群判别','非空并对ab⁻¹等运算封闭可作为群中判别条件。','加法写成对a−b模6封闭。']],'compare',[['大群模6加法','{0,1,2,3,4,5}'],['小套 {0,3}','组合与逆都留在内部'],['小套 {0,2}','2⊕2＝4，封闭失败']],'⊕ 是模6相加；子群必须沿用大群原运算，不能另换一套规则。',[['先确认小套来自大群','0与3都是大群元素，使用的仍是相加后取模6。若为了让小套可用临时换成模2加法，就不是在检查原群的子群，而是另造一个系统。'],['列出组合与撤销','0加0为0，0加3与3加0为3，3加3余6为0；0、3的逆也都在小套。结合律已由大群继承，不必重造证明，因此这套确实仍是群。'],['一处出界立即否定','{0,2}中2与2组合得到4，而4没被选入，所以封闭失败。找到单位只是必要开头，不能因含0就宣布子群；全体组合和逆元都要满足相应要求。']],'群中的非空条件不可随意省去；空集合不满足群要求，教材判别式应连同前提使用。'),
    'dm-generated-subgroup': D('只给一张“走两格”，能走到哪些地方？','从允许反复组合和撤销，收齐生成的全部元素。','在六格转盘上只给“走2格”这张基本卡，从0开始会到2、4、0，再重复，不会到1、3、5。能由这张卡及其逆反复组成的全部动作是{0,2,4}，叫它生成的子群。生成元是起步材料，生成子群则是材料能造出的整个闭合工具箱，两者不是同一层对象。',[['生成元','起初允许使用的基本元素。','六格转盘上的2。'],['生成子群 ⟨a⟩','由生成元及逆元有限组合能得到的全部元素。','⟨2⟩={0,2,4}，运算模6加法。'],['元素的阶','反复使用该元素，首次回到单位所需的正次数。','2加三次余6为0，所以阶为3。']],'cycle',[['起点为单位 0','开始反复加2'],['先到 2 再到 4','两次不同新结果'],['第三次回到 0','生成 {0,2,4}']],'图按模6加法移动；子群包含单位，即便一开始只发了卡2。',[['从单位开始记录结果','零次使用生成元得到单位0，一次得到2，两次得到4。记录的是每个不同结果，不是把操作次数当新元素；两次不同操作过程可能得到同一张卡。'],['回到单位说明进入重复','第三次加2得到6的余数0，之后2、4、0重复。逆向走2等价于正向走4，也已在集合中，因此收齐的{0,2,4}对组合与撤销稳定。'],['生成全体与只生成一部分不同','这张卡的阶为3，所以产生3个元素；整个大群有6个元素，故2不是大群的生成元。换卡1可走遍全部位置，起步材料不同，能造出的范围也不同。']],'有限例子能一直列到重复；无限群生成子群可能无限，不能因短时间没重复就认定没有规律。'),
    'dm-cosets': D('整组平移，为什么铺成一样大的块？','手算陪集，并分清它不一定也是子群。','六格转盘取子群H={0,3}。把整组每个数都加1再取模6，得到{1,4}；加2得到{2,5}。这三组把六个数恰好铺满，且每组都两张。陪集像把完整小模板整体挪位置，不是随意挑两张，也不要求挪到的新组包含单位0，所以新组未必是子群。',[['陪集 aH','在一般群里将a与H每个元素按同一侧组合所得的集合。','加法群写a＋H，1＋H={1,4}。'],['左右陪集','aH与Ha分别从左侧、右侧组合，未必相同。','本例可交换，因此左右相同。'],['相等或不交','同一子群的两个左陪集若有重叠，便是同一个集合。','3＋H又回到H，不产生新组。']],'branches',[['原子群 H','{0,3}'],['整体加 1','{1,4}'],['整体加 2','{2,5}']],'三组是模6加法群的陪集；“加1、加2”作用于组内每个元素。',[['先确保原模板是子群','H={0,3}在模6加法下是子群，再拿同一个a与每个成员组合。a=1得到1+0与1+3的余数，即{1,4}，不能只移动组里一个成员。'],['换代表可能得到同一整组','a=4时得到{4,1}，仍与1+H相同；代表名字不同不代表陪集不同。六个代表只产生三份不同的组，因为每个元素都落入其中一份。'],['平移不等于仍含单位','{1,4}不含0，不是子群，却是合法陪集。平移是双射所以每组与H同样大，一旦两组共享成员，子群的逆与封闭性质会迫使两组完全相同。']],'加法群的左右陪集相同，不能据此推断所有群都如此；一般群要尊重运算次序。'),
    'dm-lagrange': D('六张卡铺成每组两张，组数为什么是整数？','从等大陪集推出子群大小整除有限群大小。','模6加法群被H={0,3}的陪集分成{0,3}、{1,4}、{2,5}。没有重叠，没有漏项，而且每组两张，所以6＝3×2。拉格朗日定理就是把这个铺法推广：有限群的子群可以用一样大的陪集铺满全体，因此子群元素数一定整除群元素数。',[['群阶 |G|','有限群中元素的总数。','本例 |G|=6。'],['指数 [G:H]','子群H在G中的不同左陪集数量。','本例共3组。'],['拉格朗日定理','有限群有 |G|=[G:H]|H|。','6=3×2，因此2整除6。']],'flow',[['子群有两张','H={0,3}'],['陪集等大铺全体','三组，各两张'],['得到整除关系','|G|=3×2=6']],'定理前提为 H 是 G 的子群且 G 有限；不是任意两元素子集都可这样铺。',[['证明的材料来自陪集性质','每个陪集都与H一一对应，所以同样大；两个陪集相等或不相交，且全体元素都在某一陪集。三个事实共同保证可以用整组计数，而不是随便凑数字。'],['有限总数按组数相乘','群被分成k个不同陪集，每组|H|个元素，所以|G|=k|H|。k是组数，自然是整数，于是|H|整除|G|；本例k=3得到6=3×2。'],['只能按允许方向使用结论','若某子集大小不整除|G|，它肯定不是子群；大小整除却不能保证它是子群，更不能不检查运算直接宣布。定理是必要限制，不是对任意子集的充分许可证。']],'元素阶也整除有限群阶，因为它生成一个子群；不可无条件反推每个除数都对应所需子群。'),
    'dm-cyclic-group': D('一张卡反复使用，能不能走遍所有格？','从轨迹判断生成元，区分循环与交换。','六格转盘从0不断加1，会走0、1、2、3、4、5再回0；加5则反方向也走遍。可加2只到0、2、4，走不到其余格。一个群若有某个元素能反复组合生成全体，就叫循环群。关键是存在一张足够用的基本卡，不是说图画成圆圈就算循环。',[['循环群','存在一个元素生成整个群的群。','模6加法由1生成。'],['生成元','能靠自身整数次组合产生全体群元素的元素。','模6加法的1与5。'],['互素判别','模n加法中，a是生成元当且仅当a与n互素。','2与6有公因数2，所以不行。']],'compare',[['反复加 1','六个位置全到'],['反复加 5','反向也全到'],['反复加 2','只到 0、2、4']],'元素是模6余数，反复加法是群中的幂次概念在加法记号下的写法。',[['轨迹要覆盖每一个元素','由1开始不断组合，前六次不同结果覆盖0到5，因此⟨1⟩就是整个群。只回到起点并不够，还需确认回去前是否漏掉元素，卡2就是会漏的例子。'],['不同基本卡都可能够用','5在模6里等价于往回走1格，所以也走遍六格。生成元不是唯一名额；求全部生成元时要检查所有候选，不能找到一个就宣布只有它。'],['循环一定交换但反向不一定','同一元素的若干次组合只取决于总次数，所以循环群可交换。但某些交换群仍需要不止一个生成元，因此“运算交换”不足以证明循环，条件不能倒着用。']],'本课互素判别针对模n加法循环群；不能把余数数字的互素条件套进任意抽象群。'),
    'dm-permutation-group': D('三张座位卡怎样换人，先写清每人去哪里','把置换视为可逆的重新安排，按约定合成。','三个座位标1、2、3，一次轮换让1去2、2去3、3去1。这张重排规则可以写成循环(1 2 3)。它不是把数字相乘，而是在记录映射路线。再做另一张重排卡时，要先跟第一张走到中间位置，再按第二张去最终位置；每个人都必须跟到底。',[['置换','一个集合到自身的双射，表示无碰撞无遗漏的重排。','1→2、2→3、3→1。'],['循环记号','把连续被送往下一位置的对象写在括号内，末尾回开头。','(1 2 3)表示三人轮换。'],['复合次序','本课采用函数约定：右边先做，左边后做。','στ先按τ，再按σ。']],'cycle',[['原位置 1','轮换后去2'],['原位置 2','轮换后去3'],['原位置 3','轮换后去1']],'本图是单次(1 2 3)的映射，不是把1先算成2再当同一对象连续替换全部名单。',[['逐个原位置记录目标','循环(1 2 3)同时规定三个输入的输出。先为1写2、为2写3、为3写1，避免用修改后的名单覆盖原始身份；没有写入循环的其他元素按该记号约定不动。'],['合成时跟踪同一个对象','若复合στ，就对每个输入先应用右侧τ，得到中间位置，再应用σ。中间位置必须接正确；即使两个置换都只换几个人，先后反转也可能得到不同结果。'],['撤回与反复使用都能验算','(1 2 3)的逆是反向轮换(1 3 2)，两者合成各人回原位。它连续做三次也回原位，所以阶为3；阶统计需要的正次数，不是括号里数字相加。']],'有的教材采用不同复合方向，必须先声明；循环记号也不是普通代数括号，不能按乘法读。'),
    'dm-symmetry-noncommute': D('先照镜子再旋转，结果为什么会变？','跟踪正方形一个顶点，看到次序不交换。','正方形顶点按顺时针标1、2、3、4，1在左上。动作R是顺时针转90度，F是关于竖直中线镜像。若先F后R，1先到2再到3；若先R后F，1先到2又回到1。仅一个顶点去向不同，就知道两次组合不是同一个动作。可逆动作能成群，不代表可以随意换顺序。',[['对称变换','把图形变换后仍与原图形位置形状吻合的可逆动作。','正方形的旋转与反射。'],['二面体群','正多边形的旋转与反射按复合组成的群。','正方形有8种这类对称。'],['非交换','存在a、b使先后交换后效果不同。','先F后R与先R后F。']],'compare',[['固定顶点编号','1左上，2右上，3右下'],['先 F 再 R','1→2→3'],['先 R 再 F','1→2→1']],'4 为左下；R 顺时针90度，F 为竖直中线反射，始终按固定平面位置追踪。',[['先固定图和动作的含义','顶点编号沿顺时针1到4，镜像交换左右，旋转把每个位置顺时针移一格。若编号或镜轴途中改变，结果将无法比较，所以先画固定坐标与方向。'],['第一条路线连续跟同一顶点','顶点1经镜像F到右上位置2，再顺时针旋转R到右下位置3。我们追踪的是最初那一块标记，不是第二步重新随便选一个名为1的位置。'],['另一顺序出现不同终点','先旋转1到2，再镜像把2送回1。同一初始顶点分别到3与1，已经足以证明两个变换不同；无需所有顶点都不同，非交换只需要一组反例。']],'图形的对称群与所有顶点置换群不同，前者只收保持几何图形的那些置换，不能混算元素数。'),
    'dm-normal-subgroups': D('把整组放左边或右边，能不能得到同一组？','理解正规比普通子群多出的相容条件。','模6加法取H={0,3}，整体加1得到{1,4}，无论1放左边还是右边都一样，因为这里加法交换。但在旋转反射之类不交换的群里，左移与右移小组可能不同。正规子群要求对每个外部元素，这两种陪集始终相同，使按组忽略差异的规则不因左右环境而冲突。',[['正规子群 H◁G','对每个a，左右陪集aH与Ha相同的子群。','交换群中的子群都满足。'],['共轭 aHa⁻¹','对H的每个元素先后接a和a的逆，整体改变观察方式。','正规等价于这些集合仍等于H。'],['陪集相同','比较的是整份集合，不要求每项逐一同样排列。','aH＝Ha 不等于要求所有ah＝ha。']],'compare',[['先确认 H 是子群','模6加法 H={0,3}'],['左侧整体加 1','1＋H={1,4}'],['右侧整体加 1','H＋1={1,4}']],'本图是交换群内的容易例子；一般正规性要对所有a检查，不是只试一个。',[['先有子群再加额外要求','正规子群首先必须是子群，拥有封闭、单位与逆。单纯发现左右平移某次相等，不能省去基本资格；它是子群的一个更强分类，不是另一种完全无关对象。'],['比较整份左右陪集','本例加法交换，a加每个h与h加a逐项都相同，故对任意a成立。一般不交换群里仍可能整集合相同，但对应的h会变，不能误读成所有元素都彼此交换。'],['这一条件为按组计算铺路','把H内差异看作可忽略时，希望换代表、左右接其他元素都不改变最终组别。正规性提供这种一致性，后续才能把陪集当新元素组成商群；普通子群未必具备。']],'正规性是整集合的相容条件，不等于H里每个元素都与G中每个元素交换。'),
    'dm-quotient-group': D('每组当一张新卡，选谁代表都不能算出不同组','用模6按H={0,3}分组构造商群。','六张余数卡分成H={0,3}、A={1,4}、B={2,5}。现在不再区分同组内数字，把整组当一张新卡。例如A加A，选1与1得到2在B；选4与4得到2也在B；其他代表也应落B。只有代表怎么换都不影响组别，按组运算才真正定义清楚，这正是商群的关键。',[['商群 G/H','以正规子群的陪集作为新元素、按代表组合诱导运算的群。','本例只剩H、A、B三张组卡。'],['代表元','从某个陪集中暂取一个元素帮助计算。','A可用1，也可用4代表。'],['良定义','同一输入对象的不同表示不会给出不同结果。','A+A不管选哪个代表都应为B。']],'flow',[['先把元素按组归档','H={0,3}，A={1,4}'],['每组当新对象','再有 B={2,5}'],['用代表算后归组','A⊕A=B，与代表无关']],'模6加法群的H正规；所有相加先取模6，再判断结果所在陪集。',[['先把元素层次提高一层','商群里一个元素是一整个陪集，不是数字1或4本身。A与{1,4}是同一新对象的两种名字，选1计算并不意味着把A永久缩成数字1。'],['用不同代表交叉验证','1+1=2，1+4=5，4+1=5，4+4模6为2，结果都在B。因此A+A=B没有代表歧义。其他组对也要满足同样要求，不能只试成功一个例子就替代一般论证。'],['正规性保证全体相容','一般群若H不正规，代表不同可能使乘积落入不同组，运算便不成立。正规条件保证可以一致定义(aH)(bH)=(ab)H，并由大群继承单位与逆，得到真正的新群。']],'商群不是从原群删掉H，也不是把每组成员数字相加当元素；它改变了“一个元素”所指的层次。'),
    'dm-homomorphism': D('先算再翻译，和先翻译再算能一样吗？','用余数压缩理解保运算、核与像。','把模6加法卡翻译成奇偶卡：0、2、4译成0，1、3、5译成1。先把两个原卡相加再看奇偶，与先看奇偶再按模2相加，总得到同样答案。这叫保运算的翻译，也就是同态。翻译可以压缩信息，把不同数字合成同一标签，不要求每个原名都能找回来。',[['同态 f','满足 f(a*b)=f(a)·f(b) 的保运算映射，两边运算可以不同。','模6余数取奇偶到模2。'],['核 ker f','被映到目标单位元的所有原群元素。','0、2、4 都映到目标单位0。'],['像 im f','实际能翻译得到的目标元素集合。','本例可得到0与1。']],'flow',[['原群先加','1⊕3＝4（模6）'],['再翻译为奇偶','4 映成 0'],['另一条路对照','1⊕1＝0（模2）']],'左运算是模6加法，右运算是模2加法；图只演示一组，完整同态须证明全部输入。',[['先把两边运算分别写明','原边用模6，目标边用模2，不要因都写加号就忘记取余规则。f把一个原元素变成奇偶标签，是一个函数；是否同态还需它与运算配合。'],['两条路线必须输出同一标签','先在原边算1+3得4再取奇偶是0；先翻译1与3都为1，在模2中相加也为0。同态要求每对输入都有这种一致性，可从奇偶与加法的一般规则证明。'],['压缩丢了什么由核看出','0、2、4都被翻译成目标单位0，形成核。像则是实际到达的标签。本例不同原元素同译一值，说明同态不必单射；保持组合规则与保留全部身份是两回事。']],'核定义依赖目标单位，不能把“映成普通数字0”机械套进以乘法记号表示的群。'),
    'dm-isomorphism': D('换名字之后，操作表能不能完整对上？','把双射与保运算一起作为结构相同的证据。','模2加法有0、1两张卡，灯的切换动作有“不动”和“翻转”两张卡。把0叫不动、1叫翻转：两次翻转等于不动，恰好对应1加1余2为0。每张卡都有唯一新名，组合结果也对应，这两套东西虽然外观不同，却共享同一套群结构，叫同构。',[['同构','双射且保持运算的映射。','0↔不动，1↔翻转。'],['结构不变量','改名不会改变的性质，可用于排除同构。','元素数量、元素阶、是否交换。'],['同态与同构','同态可压缩；同构还要求不撞名不漏名，可完整换回。','奇偶压缩不是模6到模2同构。']],'compare',[['数字卡 0','对应不动动作'],['数字卡 1','对应翻转动作'],['检验组合','1⊕1=0，对应翻两次不动']],'灯动作只看0或1状态的整体变换；不是将某一次亮灯状态与群元素混同。',[['先给出一一对应的字典','两套各两张卡，明确0映不动、1映翻转，既无碰撞又无遗漏。只说二者大小相同不足够，同样大小的系统仍可能有不同操作规则。'],['再逐项检查操作是否翻译一致','不动与任何动作组合保持该动作，对应0加任何卡不变；两次翻转回原状态，对应1+1模2得0。字典与运算相容，才证明不只是数量相同。'],['必要条件适合快速排除','若数量不同或一个群交换另一个不交换，可立刻排除同构；但几个不变量相同仍不一定足够证明。证明通常要交出完整双射并核查保运算。']],'同构说的是当前指定运算结构，不是对象所有现实属性都一样；换研究结构时结论可能改变。'),
    'dm-ring': D('同一盒卡，两套算法怎样配合？','分开检查加法、乘法与连接两者的分配律。','模6余数卡既能相加，也能相乘，每次都取除以6的余数。加法能撤销，例如1加5回0；乘法则能连续组合，还要与加法满足分配。环就是把这两套操作配合起来研究：不能只因写了加号和乘号就以为它们有普通实数的一切性质，例如模6中的非零数2就没有乘法逆元。',[['环','加法为交换群，乘法结合，并对加法左右分配的结构。','模6加法与乘法。'],['分配律','乘法按规则作用到加法各项。','a(b+c)=ab+ac，另一侧也需成立。'],['幺环约定','是否把乘法单位1列为环的必要条件，各教材可能不同。','本例有单位1，零环等边界另按教材。']],'layers',[['加法这一套','封闭、交换、单位0与逆'],['乘法这一套','封闭且结合'],['两套相互配合','乘法对加法左右分配']],'示例模6环有乘法单位且乘法交换；一般环不因此自动交换或每个非零元素可除。',[['先分别审查两套运算','加法要求每个元素都能加逆元，且可交换；乘法要求结合。不能把加法中的逆元自动当乘法逆元，−a 与 a的倒数分别服务不同运算。'],['再检查桥梁规则','分配律把乘法与加法连接，例如2乘(1+2)模6得0，2×1+2×2模6也得0。但单个例子只帮助理解，完整结构需对所有元素成立。'],['缺的能力不能自己补上','模6里2乘3得0，尽管2、3都非零；2也找不到乘法逆元。所以环比域要求弱。教材若约定环必须有1，判定时要加检查，不能悄悄切换定义。']],'一般环的乘法未必交换；此处用模数例子入门，原教材对幺元与零环的约定仍须保留。'),
    'dm-domain-field': D('非零能约掉，和非零都能除，是两级能力','用模6与模5对照理解零因子、整环和域。','模6里2乘3余6为0，两张非零卡竟能合成零，因此不能照搬普通除法。换到模5，1到4每张非零卡都有搭档乘成1：1配1、2配3、4配4，这才可以用乘法逆元除。整环排除非零相乘成零，域更要求每个非零元素都能乘法撤销。',[['零因子','非零元素与某个非零元素相乘得到零。','模6中2与3。'],['整环','通常指有1且1≠0的交换环，无零因子。','整数是整环但非零整数不一定可除。'],['域','非零元素在乘法下构成交换群的环。','模5余数构成域，2的乘法逆元是3。']],'compare',[['模6有非零乘成零','2×3≡0'],['整数无此问题','却找不到整数中的1/2'],['模5每个非零可撤','2×3≡1，4×4≡1']],'模6与模5分别按各自模数运算；域与整环采用有1且1≠0的常见约定。',[['先抓住除法会坏在哪里','若a非零且ab=ac，却可能因a是零因子而b≠c，约掉就会出错。模6的2乘1与2乘4同余，就是这种信息丢失；普通数的经验不能无条件移植。'],['无零因子不等于都有倒数','整数没有非零相乘成0，可以作相应消去，却不能让2在整数内找到乘成1的搭档。整环保住一部分除法推理，但未保证解方程结果仍在集合内。'],['域把非零撤销补齐','模5里逐个非零元素都能找到乘成1的逆元，因而组成乘法群。有限整环还可推出是域，但“有限”不可省，整数正好是无限反例。']],'模n环是域当且仅当n为素数；边界n与环定义要明确，不可见模运算就默认能除。'),
    'dm-lattice-order': D('两份要求总能找最佳共同下限与上限','从子集偏序亲手找交与并所扮演的角色。','两份物品清单{a,b}与{b,c}，共同保证包含的最大清单是{b}；能够罩住两者的最小清单是{a,b,c}。若一个偏序里每对对象都有这样两种最佳界，就叫格。格不要求两份清单谁包含谁，只要求这对对象的共同上下界各有最合适的一位。',[['格','每对元素都有最大下界与最小上界的偏序结构。','全部子集按包含构成格。'],['交 ∧ / Meet','两元素的最大下界，不是随便一份下界。','本例为共同部分{b}。'],['并 ∨ / Join','两元素的最小上界。','本例为合并清单{a,b,c}。']],'layers',[['两份待比较清单','{a,b} 与 {b,c}'],['最大的共同下界','{b}'],['最小的共同上界','{a,b,c}']],'集合格中交并恰是集合交并；一般格的元素未必是集合。',[['先允许两份清单不可比','{a,b}缺c，{b,c}缺a，所以谁都不是谁的子集。格不要求排成一条直线，而是问即便不可比，是否仍能找到两者的最佳共同界。'],['下界中挑最大的一位','所有同时包含于两清单的对象都只能用共同成员b，所以{b}是最大下界。它不只是极大，而是其他下界都包含于它；记为两清单的交。'],['上界中再挑最小的一位','要罩住两清单必须至少有a、b、c，所以{a,b,c}是最小上界。每对都拥有两种界才是格，检查一个成功对子只是示范，不能证明整个偏序都满足。']],'一般偏序可能有界却没有最佳界，也可能缺界；不能把某幅图有顶有底就直接当成格。'),
    'dm-lattice-algebra': D('先求共同部分再合并，为什么能吸收回原件？','把格的运算律读成上界下界之间的关系。','拿集合A={a,b}、B={b,c}。先合并A与B得到{a,b,c}，再与A取共同部分，又回到A，因为合并结果本来就包含A。这叫吸收律。格可一边看作偏序，一边看作交并两套运算；交换、结合、幂等与吸收把两种视角接起来，但分配律仍是额外能力。',[['幂等律','同一元素与自己求交或并仍得自己。','A∩A=A。'],['吸收律','a∧(a∨b)=a 与对偶式。','合并后再与原件取交，回原件。'],['分配格','交对并及相应对偶分配律成立的格。','集合格成立，一般格未必。']],'flow',[['先合并两份','A∪B={a,b,c}'],['再与 A 求交','A∩{a,b,c}'],['结果回到 A','得到 {a,b}']],'此图用集合格说明吸收；符号 ∧∨ 在一般格中代表最佳界运算而非真值。',[['先用包含关系看而不是背式子','A并B必定包含A，所以再与A求共同部分恰好留下A。吸收的原因来自上下界关系，而不是恰好选了某几张字母卡，换任意A、B也一样。'],['交并保留各自的规律','最佳上下界唯一，使交换与结合等规律成立；与自己比较时最佳界还是自己，所以幂等。两种运算还必须满足吸收，这些条件一起描述格的代数骨架。'],['不要给所有格自动加分配','集合格能按元素条件证明分配，其他格可能不满足。学习格的普遍规律时要标清已知范围；只因熟悉集合交并便把它所有性质搬到任意格，会算出错误恒等式。']],'两套公理化视角相互对应需要证明；此处用集合例子理解，并不以一个例子代替一般定理。'),
    'dm-boolean-algebra': D('名单取反、判断否定、开关翻转，为何像同一种算法？','理解带上下界与补元的分配格。','全集U={a,b}中，A={a}，补集是{b}。两者交起来为空，合起来是全体。把空集叫0、全体叫1，把交并当两套运算，就会看到与真假逻辑相同的骨架：真且假为假，真或假为真，否定把两者互换。布尔代数把这种共同结构抽象出来，而不是说集合就是电路本身。',[['有界格','有小于等于所有元素的0与大于等于所有元素的1。','集合格中0=∅，1=U。'],['补元 a′','满足a∧a′=0且a∨a′=1的对象。','{a}的补为{b}。'],['布尔代数','具有补元的有界分配格。','集合运算与二值逻辑都是重要模型。']],'compare',[['清单 A 与补清单','{a} 与 {b}'],['两份共同部分','交为 ∅，对应0'],['两份完整合并','并为 U， 对应1']],'0、1是结构中的最小与最大元素名，不必是普通整数。',[['先确定全体与空白的边界','不说全集U就不能谈唯一的集合补。U的全部子集按包含形成格，空集最小、U最大，这两端分别充当抽象0与1，而不是在数成员数量。'],['补元同时满足排斥与覆盖','A与补集不能重叠，交为0；两者合起来不能漏掉全集，故并为1。只满足其中一个不够，例如空集与A虽不重叠，却未必覆盖U。'],['分配条件让补与化简可靠','布尔代数还要求格分配，不能见任何有顶底和补的格就贴标签。在该结构里可用德摩根等规律统一理解集合、逻辑与开关，但具体对象仍各有解释。']],'一般有界格的补元可能不存在或不唯一；布尔代数的分配条件不能省掉。')
  });
})();
(() => {
  const D = (plainTitle,goal,story,terms,kind,nodes,caption,steps,boundary) => ({plainTitle,goal,story,terms:terms.map(([word,meaning,example])=>({word,meaning,example})),diagram:{kind,nodes:nodes.map(([name,detail])=>({name,detail})),caption},steps:steps.map(([title,text])=>({title,text})),boundary});
  Object.assign(window.PLAIN_BEGINNER = window.PLAIN_BEGINNER || {}, {
    'dm-membership-subset': D('盒里有一张卡，还是有一盒卡？','分清把对象作为一个成员，和检查其中全部成员。','盒 A 里只有数字卡 1 和 2。卡 1 是盒 A 的一个成员，但“装着 1 的小盒子”不是卡 1 本身。符号 1∈A 问一件东西在不在里面；{1}⊆A 则打开小盒，检查其中每张卡是否都在 A 里。一层括号改变了对象身份，不能只看里面的数字相同。',[['∈ / 属于','检查一个对象是否为集合的成员。','1∈{1,2}。'],['⊆ / 子集','检查左边集合的所有成员是否都属于右边。','{1}⊆{1,2}。'],['∅ / 空集','一个成员都没有的集合，不是数字零。','∅ 是任意集合的子集。']],'compare',[['检查数字卡 1','1∈A 为真'],['检查小盒 {1}','{1}⊆A 为真'],['小盒本身也是物品','{1}∈A 为假']],'A＝{1,2}；集合是数学对象，“盒子”只帮助区分层次。',[['属于只检查眼前这一件','问 1∈A，就在 A 成员清单上找数字 1，不拆开任何别的对象。若问 {1}∈A，找的是整个集合 {1} 这个对象；A 仅有两个数字，所以找不到。'],['子集要把左边逐个拆看','问 {1}⊆A，左边是集合，要检查其所有成员是否都在 A。它只有成员 1，且 1 在 A 中，因此子集关系成立，与小盒本身是否是 A 的成员无关。'],['空集为何总是子集','要推翻子集关系，须找左边一个不在右边的成员。空集没有任何成员，自然找不出反例，所以是任意集合的子集；但空集不一定是任意集合的一个成员。']],'花括号不是装饰；集合可以作为另一个集合的成员，此时要按原题给定层次判断。'),
    'dm-set-description': D('把合格卡片筛出来，顺序不重要','读懂按条件定义集合，理解相等看成员而非排列。','桌上自然数卡 1 到 6，规则是留下偶数。筛完得到 2、4、6，可以直接列出，也可以写“从这六张里挑偶数”。两种写法描述同一个集合。把 6 写在前面，或把 2 重写一次，都不会凭空增加成员，因为集合关心哪些对象被选中，而不记录次序与重复次数。',[['列举法','把成员逐个写在花括号内。','{2,4,6}。'],['描述法','先给范围，再用条件筛选。','{x∈{1,…,6}｜x是偶数}。'],['集合相等','两个集合具有完全相同成员。','{2,4,6}＝{6,2,4}。']],'flow',[['先定候选范围','自然数 1 到 6'],['按条件逐张筛','只保留偶数'],['记录选中成员','得到 {2,4,6}']],'竖线读作“使得”；范围和条件共同决定集合。',[['别把筛选条件悬空','“所有偶数”与“1 到 6 里的偶数”不是同一个集合。读描述法先看变量从哪来，再看要满足什么；范围扩大或条件改变，都可能改变最后留下的成员。'],['逐张检查构造结果','1 不合格、2 合格，如此得到 2、4、6。描述法中的 x 只是逐个候选对象的名字，竖线后是筛选标准，不是另一项要放进集合的成员。'],['相等只看成员有没有差异','两集合相等要两边每个成员都能在另一边找到，排列次序不影响。重复写同一个成员不会让它多占一个数学成员；若题目研究顺序或次数，应改用序列或多重集。']],'集合不记录重复和顺序；排队名单、带次数统计等问题不能直接按普通集合处理全部信息。'),
    'dm-power-set': D('两样物品，有几种打包选法？','把一种选法本身当作对象，列全所有子集。','桌上有苹果和梨，打包时每样都可以选或不选。于是四种选法是都不选、只选苹果、只选梨、两样都选。把这四种选法收成一个新集合，就叫原集合的幂集。它的成员不是苹果和梨，而是“挑出的那一组”；空选法也必须算一种。',[['子集','原集合中选出的一组成员，可以一个都不选。','{苹果} 是 {苹果,梨} 的子集。'],['幂集 P(A)','把 A 的所有子集作为成员构成的集合。','P({苹果,梨}) 含四个集合。'],['2ⁿ','n 个成员各有选或不选两种独立选择，总共的选法数。','两样为 2×2＝4。']],'branches',[['苹果选不选','两种选择'],['梨选不选','每支再分两种'],['汇总完整选法','∅、{苹果}、{梨}、{苹果,梨}']],'每个终点是一整个子集，不是单独一个水果。',[['每件都有两个按钮','先只看苹果：选或不选。再看梨：无论苹果选没选，梨仍有两种选法，因此总数相乘。n 件不同物品就有 n 个独立二选一，得到 2 的 n 次方。'],['把一次选择装成一个对象','只选苹果得到集合 {苹果}，它是幂集的一个成员。苹果本身是原集合成员，不是本例幂集里的集合对象；看到幂集要主动上移一层括号。'],['空选法与全选都别漏','完全不选产生 ∅，全部选择产生 A 本身。二者也都是子集，所以必须进入幂集。原集合若空，仍有唯一的空选法，因此其幂集是 {∅} 而不是空集。']],'公式 2ⁿ 在这里用于有限 n 个不同成员；重复写同一物品不增加集合成员数。'),
    'dm-set-operations': D('两个社团，怎样筛出要通知的人？','让每个人回答在不在 A、在不在 B 两个问题。','A 是篮球社，B 是音乐社。要通知任一社团成员，就取两个名单的并；只通知两社都参加者，就取交；只通知篮球社但不在音乐社者，就取差。同一个人可能同时在两表中。集合运算不是在移动符号，而是给每个候选人一个是否入选的规则。',[['A∪B / 并','至少属于两集合之一。','篮球或音乐社成员都要通知。'],['A∩B / 交','同时属于两个集合。','两社都参加。'],['A−B 与补集','A−B 要在 A 不在 B；补集要在指定全集里却不在 A。','补集必须先知道全体候选人。']],'compare',[['同时在两社','并、交入选，A−B不选'],['只在篮球社','并与 A−B 入选'],['两个都不在','并、交、差都不选']],'补集必须相对于指定全集，例如本班全体同学。',[['先只贴两个成员标签','每个人只需回答是否在 A、是否在 B，共四种真假组合。不必被名单顺序干扰，也不能把同时参加者当成两个人；运算作用于成员资格而不是名单行数。'],['把运算读成筛选条件','并是至少一个标签真，交是两个都真，差 A−B 是 A 真且 B 假。交换并与交的左右不影响结果，但 A−B 换成 B−A 会改变要通知的人。'],['补集先要有全体候选','“不在篮球社”的人若不限制范围，可能包含全世界。指定全集为本班后，补集才是班里不参加篮球社的人。补集不是所有未知对象，范围是定义的一部分。']],'同一问题的全集应固定；改变全集会改变补集，差集也不满足任意交换左右。'),
    'dm-set-identities': D('不必背图形，逐个人检查资格','用同一个成员的真假条件证明集合两边相同。','要说明“不参加篮球或音乐任一社团”就是“篮球不参加且音乐不参加”，可以随便挑一个人，逐项翻译资格。只要原规则对这个任意人和新规则完全一致，两份名单就相同。集合恒等式的证明，核心就是所有成员的入选条件一致，不是两边画出来像。',[['成员法','取任意对象，比较它属于两边的充要条件。','x∈左边 当且仅当 x∈右边。'],['德摩根律','否定并变成两边否定后的交，否定交变成两边否定后的并。','(A∪B)补＝A补∩B补。'],['分配律','把交与并按规则展开，保持成员条件不变。','A∩(B∪C)＝(A∩B)∪(A∩C)。']],'flow',[['任取候选人 x','检查 x 不在 A∪B'],['拆开失败条件','不在 A，并且不在 B'],['重新写成集合','x 在 A补∩B补']],'补集都相对于同一固定全集；x 取任意对象而非只挑例子。',[['取一个没有特殊身份的对象','设 x 是全集内任意成员，然后翻译 x 在左边到底要求什么。任意很关键：若只拿一个恰好符合的人检查，不能代表其他人，也不能证明整份名单一致。'],['用逻辑把资格条件拆清','x 不在 A∪B，表示它既不在 A 也不在 B。“不在至少一个社团”与“至少一个社团不在”不同，前者要两个都不在，须逐句确认否定作用的范围。'],['再把条件译回另一份名单','既不在 A 又不在 B，正是属于 A 的补集与 B 的补集之交。每个 x 左右资格等价，因此成员完全一致。做分配律也按这个路线逐步拆与合。']],'画图能帮助找规律，但严谨结论需要覆盖全部成员；只有某一组具体集合相等不足以证明恒等式。'),
    'dm-cartesian-product': D('衣服配裤子，搭配本身也算一种对象','理解有序对、配对表与顺序不可随意交换。','有红、蓝两件上衣，黑、白两条裤子。每件上衣可配每条裤子，共四套。我们把一套写成“上衣、裤子”的有序对，第一格与第二格有固定角色。所有可搭配的有序对构成笛卡尔积；它不是把两份物品混到一个袋子里。',[['有序对 (a,b)','两个位置各有角色的对象，交换位置通常改变对象。','(红上衣,黑裤) 与反向角色不同。'],['A×B','所有第一项取自 A、第二项取自 B 的有序对。','两件上衣配两条裤子得到四对。'],['积的计数','有限且所有配对都允许时，配对数为两边成员数相乘。','2×2＝4。']],'branches',[['先选上衣','红或蓝'],['再选裤子','每种上衣都配黑或白'],['记录完整搭配','四个有序对']],'图表示所有组合均允许；若另有搭配限制，需进一步筛选关系。',[['先固定两个位置的角色','第一项来自上衣集合，第二项来自裤子集合。红上衣本身不是一整套，黑裤子也不是；只有两格按角色配好才得到积集合的一个成员。'],['每个第一项遍历第二项','红上衣配黑裤、白裤，蓝上衣也各配一次。不会漏配，也不会重复同一有序对，所以有限计数可用乘法；任一边空，便无法凑成完整配对。'],['顺序改变就是另一个类型','A×B 与 B×A 通常不是同一个集合，因为第一第二位置互换。即使二者数量相同，也不能据此说成员相同；有序对与普通无序集合的规则不同。']],'配对计数相乘要求全部组合都允许；二元关系是在这个配对范围内再选出符合条件的部分。'),
    'dm-pigeonhole': D('四个人放进三个房间，躲不开一次同住','自己选对象与抽屉，解释至少存在的保证。','安排四位同学住三间房。再聪明的安排也不可能让每房最多一人，因为那样只能装下三人。因此至少一间住两人。这种证明不需要指出具体哪间，只说明无论怎么分，都至少有一处超过容量；难题常在于把题中的对象归入合适类别。',[['抽屉原理','多于 n 个对象放入 n 类，至少有一类不少于两个。','四人分三房。'],['广义保证','m 个对象入 n 类，至少一类不少于向上取整的 m/n。','十人三房至少一房四人。'],['向上取整','取不小于给定数的最小整数。','10/3 约3.33，向上取4。']],'flow',[['假设每房最多一人','三房最多三人'],['实际有四个人','容量不够'],['否定原假设','至少一房有两人']],'原理保证至少一处达到数量，不确定具体哪处，也不要求均匀分配。',[['先明说谁是对象谁是类别','本例人是待分对象，房间是抽屉。生日、余数、颜色都能当其他题的抽屉，但必须保证每个对象确实归入所规定的类别，类别数也须算对。'],['用最多能容纳多少反过来想','若每房最多一人，三房总共最多三人，与四人都安排进去矛盾。这里真正推动结论的是总数超出容量，而不是假设每房分得一样多。'],['一般化时检查差一人的边界','若要保证某房至少 k 人，反想每房最多 k−1，则 n 房至多 n(k−1) 人；再多一人就必须突破。这样能推导保证人数，避免直接除完忘记整数边界。']],'抽屉原理通常证明存在，不直接构造唯一对象；用它求“保证”要同时考虑少一人能否避开。'),
    'dm-inclusion-exclusion': D('两个社团人数相加，谁被算了两遍？','按每个人被统计的次数修正总数。','篮球社有 5 人，音乐社有 4 人，其中 2 人同时参加。直接 5＋4 会让这 2 人各被点名两次，想统计至少参加一个社团的不同人数，就要各减回一次，得到 7。容斥不是神秘公式，而是让每个合格对象最后恰好被算一次。',[['容斥原理','对重叠统计作加减修正，使对象得到正确计数。','两集并人数＝5＋4−2。'],['至少一个','属于任一集合即可，包括同时属于多个。','同时参加两社的人仍在并集里。'],['恰好一个','属于一个而不属于另一个。','两社人数和须减两次重叠人数。']],'flow',[['先相加两社人数','5＋4＝9 次点名'],['找出重复人群','2 人各被算两次'],['各减回一次','9−2＝7 个不同人']],'例中 2 为交集人数；至少一个与恰好一个不是同一数量。',[['不要先背加减号','先任取一个仅参加篮球社的人：相加时被算一次。再看同时参加两社的人：在两份名单里都被算，共两次。过多的那次就是需要修正的部分。'],['减一次保留一次','统计并集时，两社都参加者也应计入，只是不能重复，所以减去交集一次。若求恰好一社，交集者应最终零次，就要从两社人数之和中减去两次交集。'],['三份名单继续逐次核账','三个集合先加单个、减两两交集后，三者共有的人会被算成零次，因此还要加回三者交集。用一个人的出现次数检查，能解释每个符号为何必要。']],'公式中的交集必须允许同时属于更多集合的人；题目给“只参加这两个”的人数时不能直接混用。'),
    'dm-binary-relation': D('把所有可能搭档列出来，再勾出允许的','把文字规则、配对清单、表格和箭头对应起来。','三位同学之间谁向谁借过书，可以先列出所有“借书者、出借者”配对，再把真的那些勾出来。关系就是这些被选中的有序对。画成表时行是借书者、列是出借者；画成箭头时从第一人指向第二人。同一信息换了画法，方向角色仍不能换。',[['二元关系','从某个笛卡尔积里选出的有序对集合。','(甲,乙) 表示甲向乙借过书。'],['关系矩阵','用行列对象标号，以数字表示配对是否入选。','甲行乙列的 1 对应箭头甲→乙。'],['关系图','用点代表对象、箭头代表选中的有序对。','双向借过要画两条反向箭头。']],'flow',[['固定配对角色','第一位借书，第二位出借'],['按事实勾配对','选 (甲,乙)、(乙,丙)'],['换成箭头与矩阵','甲→乙，乙→丙']],'同一集合上的关系允许自配对，但是否选择自环由具体规则决定。',[['先把方向写成一句话','借书关系有方向，甲借乙不代表乙借甲。先规定有序对第一与第二位置的意义，再列所有可能配对；不先定方向，后续矩阵和箭头就容易互相颠倒。'],['选择哪些配对进入关系','若甲向乙借过，选择 (甲,乙)，否则不选。关系不需要把所有配对都收进来，也不要求每个人只有一个对象；那是函数才会施加的额外条件。'],['换画法时保持坐标约定','在甲行乙列填 1，与画甲→乙表达同一事实。矩阵中每格、清单中每对、图中每箭头应能互查，发现不一致先查行列顺序而不是改事实。']],'日常“有关系”常含双向意味，数学二元关系没有自动对称性；必须根据定义逐对判断。'),
    'dm-relation-operations': D('两套箭头怎样合并、求共同或全部反向','把运算落实到每一条有序对。','关系 R 记录甲能给谁发消息，S 记录另一种通信方式。任一方式可达就合并箭头，两种方式都可才留下共同箭头。把每条箭头反过来，则是在问谁能给甲发消息。逆关系总能反转箭头，却可能让同一起点对应多人，因此不一定还是函数。',[['并与交','关系本身也是集合，并取任一有序对，交只留共有配对。','R∪S 收齐两种箭头。'],['逆关系 R⁻¹','将每个有序对 (a,b) 改成 (b,a)。','甲→乙 变乙→甲。'],['逆关系与逆函数','前者总能作；后者还要求反向满足函数等条件。','两人指向乙，反向乙就有两条路。']],'compare',[['原关系两条箭头','甲→丙，乙→丙'],['逐条倒转方向','丙→甲，丙→乙'],['检查是否函数','丙对应两人，不是函数']],'上标 −1 在此表示逆关系，不是数值倒数；定义域陪域随方向交换。',[['先按有序对集合做并交','一条箭头在 R 或 S 中出现，就进入并；必须在两者都出现才进交。重复箭头不算两次，因为关系是集合，名称换成关系并未改变集合运算规则。'],['反转每条箭头而不添故事','逆关系只做 (a,b) 到 (b,a)，不要求现实里已经发生反向通信。它描述原关系的逆向查询；不要把数学反向当成两人真的各自发过消息。'],['再看反向是否满足函数要求','原来甲乙都指丙，反转后丙同时指甲乙。关系允许这样，但函数的每个输入只能有一个输出。故存在逆关系不等于存在同类型的逆函数。']],'函数的逆还要检查一一对应和所定定义域、陪域；不能见到反向箭头就直接叫逆函数。'),
    'dm-relation-composition': D('经一个中转人，两段关系接成一段','找出中间对象，再记录起点与终点。','甲认识乙，乙会帮助丙，因此甲可以经过乙找到丙。关系复合记录这种两段衔接，但要求同一个中间人同时接上两段。它不是把两张名单简单相加，而是逐个起点寻找存在的中转点，再把起终点记成一个新配对。',[['关系复合','先经过一个关系再经过另一个，把可衔接的起终点组成新关系。','甲→乙→丙 产生甲→丙。'],['中间对象','同时是第一段终点与第二段起点的对象。','两段都必须用同一个乙。'],['记号约定','不同教材对 R∘S 的阅读顺序可能不同，必须先确认。','本图只按口头“先 R 后 S”。']],'flow',[['先走关系 R','甲→乙'],['再从同一乙走 S','乙→丙'],['记下复合关系','甲→丙']],'图按“先 R 后 S”解释；符号 R∘S 或 S∘R 必须与教材约定对应。',[['从一个起点查第一段','先看甲能通过 R 到哪些中间人，不只凭原图的几何距离。若甲通过 R 到不了任何人，就不可能以甲为起点完成本次两段衔接。'],['把第一段终点交给第二段','若第一段到乙，第二段必须从乙出发。另一条丁→丙 不能拿来接甲→乙，因为中间身份不同。只要存在一个合适中间对象，就足以让起终点进入复合。'],['记录时可以有多种中转','甲经不同人都能到丙，复合里仍只写一个有序对 (甲,丙)，不统计路径次数。若交换先后，能衔接的中间点可能改变，因此关系复合一般不交换。']],'复合关系只记录是否存在中间对象，不保留选了哪条具体路或共有多少种路线。'),
    'dm-reflexivity': D('人人有自环、人人没自环，还是只是没凑齐？','分清自反、反自反与非自反的量词要求。','三张姓名卡上可以画“自己指向自己”的圈。如果甲乙丙都有圈，就是自反；一个圈也没有，叫反自反；若只有甲有而乙丙没有，只能说不是自反，不能说反自反。“所有都有”的否定只是“有一个没有”，并不自动变成“所有都没有”。',[['自反','集合里每个对象都与自己有关系。','每个点都画自环。'],['反自反','集合里没有任何对象与自己有关系。','一个自环都没有。'],['非自反','自反条件不成立，即至少一个对象缺少自环。','只有甲有圈也属于非自反。']],'compare',[['三个点都有圈','自反'],['三个点都没圈','反自反'],['只有甲有圈','非自反，但非反自反']],'本图取非空集合 {甲,乙,丙}，只检查对角线上自配对。',[['自反要检查每一个对象','在关系清单里分别找 (甲,甲)、(乙,乙)、(丙,丙)，全都有才自反。其他对象之间箭头再多，也不能弥补某个自己与自己关系的缺失。'],['反自反要求一个都没有','检查全部自配对都未出现，才能叫反自反。只发现乙没有圈不能完成证明，因为甲可能还有；反自反与非自反的差异就是“一个也无”与“至少缺一个”。'],['用混合例子把词分开','甲有圈、乙无圈时，自反因乙失败；反自反又因甲失败。因此它可以既非自反、又非反自反，三种表达并不是对集合做互斥二选一。']],'空集上全称条件会真空成立，自反与反自反可同时成立；不要把非空图的直觉机械推广。'),
    'dm-symmetry': D('能双向，禁双向，只禁止不同人双向','把三种性质分别说成箭头规则。','甲与乙之间若画了甲→乙，对称要求还得有乙→甲。反对称却不是把它否定，而是说不同对象不能同时双向，自环仍允许。不对称更严格：只要有正向，就不许反向，因此连自环也不许。先拿两个人和一个自环检查，比只盯词里的“反”可靠。',[['对称','每条 a→b 都要求反向 b→a。','不同人可双向，自环也不冲突。'],['反对称','若 a→b 与 b→a 同时存在，就必须 a＝b。','不同点禁双向，自己可有环。'],['不对称','有 a→b 就不能有 b→a。','因此自己也不能指自己。']],'compare',[['甲乙相互指向','允许对称，违反反对称'],['只有甲指向自己','允许反对称，违反不对称'],['只有甲→乙','可不对称，不是对称']],'名称在不同翻译中可能有差别，做题以箭头条件和教材定义为准。',[['对称像要求每条路配返程','从任何一条 a→b 出发，检查是否有 b→a。要推翻对称，只需找到一条缺返程的箭头。不是只需找到一对双向，就能证明全图对称。'],['反对称关注不同对象双向','两个不同点双向就是反例，自环却合法，因为起终点相同满足 a＝b。因此偏序关系可以既反对称又自反，两个性质没有相互冲突。'],['不对称连自环也排除','若 a→a 存在，它同时就是自己的反向，所以违反不对称。用定义可知不对称要求比反对称更多；反对称并不是对称的逻辑否定，二者甚至可能同时成立。']],'“不对称”在这里是严格性质名，日常说“不够对称”未必对应相同逻辑含义。'),
    'dm-transitivity': D('两段已经有了，必须补上直达关系吗？','对每个能衔接的两段，检查起终点关系。','关系里有甲比乙早、乙比丙早，那么甲也比丙早，这种性质叫传递。它不是说图上一定要画三角形，而是任何已有的两段，只要中间人接得上，就必须存在从起点到终点的关系。箭头画得弯曲还是直线，不影响数学上的检查。',[['传递性','aRb 且 bRc 时必须 aRc。','甲→乙、乙→丙 逼出甲→丙。'],['反例三元组','两段存在而直接关系缺失的三个对象。','找出甲乙丙及缺边即可否定。'],['重复对象','定义未要求 a、b、c 两两不同。','甲→乙、乙→甲 可能要求甲自环。']],'flow',[['第一段已有','甲→乙'],['第二段接上','乙→丙'],['检查起终点','必须有甲→丙']],'只对已经存在的可衔接两段提出要求，不要求凭空出现所有箭头。',[['从真实已有的第一段开始','任选一条 a→b，再找所有从 b 出发的箭头 b→c。中间点必须相同才能组成条件；任意两条不相接的边放在一起不产生传递义务。'],['检查要求的是关系不是路程','即使甲经过乙能到丙，若甲→丙 没列入关系，仍不传递。定义说直接有序对必须属于关系，不是只要求图上能走过去；两者不要混同。'],['反向成对也别漏掉','甲→乙 与乙→甲 可以取 c＝甲，所以传递性会要求甲→甲。检查时不能只找三个不同点的三角形，重复点也是定义允许的候选。']],'关系可能因没有任何可衔接两段而真空传递；没有三角形不自动说明不传递。'),
    'dm-relation-closures': D('只补规则逼出的箭头，补到再也不缺','理解最小闭包与反复补边为何必要。','甲能直接到乙，乙能直接到丙，丙能直接到丁。想让关系完整记录沿路能到谁，先补甲→丙还不够，因为新路又说明甲能到丁。闭包在保留原箭头的同时，只加入目标性质强迫增加的那些，不是随便把所有点互连，也不是补一轮便一定结束。',[['闭包','包含原关系且具有指定性质的最小关系。','传递闭包补齐正长度路径所对应关系。'],['迭代补边','利用已有与新补的边反复检查要求。','甲→丙 与丙→丁 又逼出甲→丁。'],['零步与正长可达','零步允许原地不动，正长要求至少走一条边。','自反传递闭包包含所有自环，传递闭包未必。']],'flow',[['原有链条','甲→乙→丙→丁'],['补两步要求','甲→丙，乙→丁'],['继续补新要求','甲→丁，直到稳定']],'图示传递闭包；自环是否加入取决于路径与所求闭包类型。',[['先说明要求哪一种性质','自反闭包补全自环，对称闭包补反向，传递闭包补可达起终点。不同目标带来不同必要边，不能见到“闭包”就默认全连；原关系必须始终保留。'],['只把被条件强迫的边加入','甲→乙、乙→丙 使甲→丙 必须加入；同理乙→丁。没有路径支持的反向边不要随意添加，否则虽可能满足性质，却不再是最小的那一份。'],['新边仍参与下一轮检查','加进甲→丙 后，它与丙→丁 又要求甲→丁。直到所有要求都满足才停止。若问允许零步可达，还应加入每点到自己的关系，不能与正长版本混淆。']],'有限图可通过有限步骤稳定；用哪种闭包及是否允许零步，应以题目记号约定为准。'),
    'dm-equivalence-classes': D('按余数分班，每个人只进一个班','从同一标准的关系得到不重叠分组。','把 0 到 5 六张卡按除以 3 的余数归档：0、3 一组，1、4 一组，2、5 一组。说两张卡同组，就是余数相同。自己与自己同组，换个顺序仍同组，通过第三张卡也仍同组，这三条性质让分组一致，不会出现两个班重叠却又不是同一个班。',[['等价关系','同时自反、对称、传递的关系，用来表达某标准下视为同类。','除以3余数相同。'],['等价类 [a]','与 a 等价的所有对象组成的集合。','[1] 在本例为 {1,4}。'],['划分','若干非空且互不相交的组，合起来恰好覆盖全体。','三组把六张卡完整分开。']],'branches',[['先定归类规则','除以 3 余数相同'],['分别收进三组','{0,3}、{1,4}、{2,5}'],['每卡恰好一组','组不重叠，覆盖全体']],'例子论域为 {0,1,2,3,4,5}；扩大论域后同余类内容会改变。',[['同类必须标准一致','自反保证每张卡归入自己的类；对称保证甲和乙同类不取决于先问谁；传递保证通过乙建立同类不会产生冲突。三者共同支撑可靠分组，不是只看名字叫等价。'],['拿一张代表卡收齐同类','用 1 作代表，收起余数也是1的卡，得到 {1,4}。代表换成4，整组不会变化。等价类是集合对象，不是代表数字本身；同一组可以有多个代表名字。'],['重叠为何会合并为同一组','若两组共含一张卡，由对称与传递可知两组所有成员都相互等价，故两组其实相同。它们不能只重叠一部分，因此得到互不相交且覆盖全体的划分。']],'“等价”只忽略当前标准下的差别，不表示对象一切属性相同；不同标准会产生不同划分。'),
    'dm-partial-order-hasse': D('有先后规则，不代表所有人都能比大小','用包含关系理解偏序与省略箭头的图。','集合 ∅、{a}、{b}、{a,b} 按包含关系排列。空集在最下，全集在最上，但 {a} 与 {b} 谁都不包含谁，不能硬排高低。偏序容许这样的不可比。Hasse 图只画不能被中间对象省略的上下连接，再默认恢复自反和传递信息，让图更清爽。',[['偏序','自反、反对称、传递的关系，允许部分对象不可比。','集合的包含关系。'],['不可比','a≤b 与 b≤a 都不成立。','{a} 与 {b} 互不包含。'],['Hasse 图 / 覆盖','只保留中间没有其他对象的上下相邻关系，通常向上表示更大。','省去 ∅ 到 {a,b} 的传递边。']],'layers',[['底部空集','∅'],['中层两个对象','{a} 与 {b} 不可比'],['顶部全集','{a,b}']],'示例采用包含偏序，图中上下不是数值坐标；上升路径代表可比较。',[['先用关系而不是高度定义大小','这里小于等于的意思是子集。∅ 包含于每个候选，而 {a} 与 {b} 各缺对方成员，所以没有前后。偏序不是把大家强行排成一列，全序才要求每对都可比。'],['相邻连接留下骨架','∅ 与 {a} 之间无候选中间者，保留连接；{a} 与 {a,b} 也保留。∅ 到 {a,b} 可经中间者推出，故在 Hasse 图省略，自己到自己的自环也不画。'],['读图时把省略条件补回','沿上升路线可推出包含关系，例如从 ∅ 经 {a} 到全集。中层两点虽画得一样高，不是因此相等，而是例图表达不可比；实际判断仍看路径和关系定义。']],'Hasse 图约定向上为较大且不画箭头；换教材朝向要先确认，不能仅凭横纵距离判断关系。'),
    'dm-maximal-maximum': D('没人比我大，和我比所有人都大','在有不可比对象时，分清局部端点与全局最大。','只看 {a}、{b} 两个集合，按包含比较。没有候选严格包含 {a}，所以它是极大；{b} 也一样。但 {a} 不包含 {b}，谁也不能称为大过全部候选的最大。极大只排除有人在自己上面，最大还要求自己与每个人都能按指定方向比较。',[['极大元','在当前集合里没有另一个严格大于它的对象。','{a} 与 {b} 都可极大。'],['最大元','大于等于当前集合的每一个对象。','若加入 {a,b}，它成为最大。'],['极小 / 最小','分别是反向的没有更小者，与小于等于全部对象。','比较方向相反，量词差别相同。']],'compare',[['只取两个单元素集','{a}，{b}'],['分别找更大者','各自没有，均极大'],['检查压过全体','谁也做不到，故无最大']],'本例偏序为包含，候选集合只有 {a}、{b}；边界随候选范围变化。',[['极大先尝试找打败它的人','对 {a}，候选里没有严格包含它的对象，所以它极大。这个检查允许另一个对象与它根本不可比；未找到更大者，并不等于它已经包含另一个对象。'],['最大要逐一面对所有候选','若称 {a} 最大，必须让 {b}⊆{a}，但不成立。换 {b} 也失败。由此可见有极大元不保证有最大元，极大还可能有多个，而最大若存在只能有一个。'],['加入候选会改变结论','把 {a,b} 加入后，它包含两单元素集，成为最大；原来两者不再极大。这些性质都针对某个指定偏序集合，不是对象脱离环境永远拥有的头衔。']],'全序有限非空情形容易把极大与最大混在一起；偏序中的不可比例子能揭示定义差异。'),
    'dm-bounds-lattice': D('给两件东西找共同屋顶，再找最低合格屋顶','区分上界、最小上界及它们所在的范围。','在 {a,b,c} 的所有子集里，想同时罩住 {a} 和 {b}，可以选 {a,b}，也可以选 {a,b,c}。这两个都是上界，但最节省且仍罩住两者的是 {a,b}，叫最小上界。它不必是原来那两个对象之一；找界要在指定环境里搜索，而不是只在目标名单中找。',[['上界','不小于目标子集每个对象的环境元素。','{a,b} 与 {a,b,c} 都罩住 {a}、{b}。'],['最小上界 / 确界','所有上界里最小的一个，而非随便一个极小上界。','本例为 {a,b}。'],['下界 / 最大下界','反方向共同不大的对象，及其中最大的。','{a} 与 {b} 的最大下界是 ∅。']],'layers',[['要一起罩住','{a} 与 {b}'],['合格的上界','{a,b}，{a,b,c}'],['选最小的上界','{a,b}']],'环境为 {a,b,c} 的全部子集，偏序为包含；目标集合与搜索环境不同。',[['先圈出研究对象与搜索环境','目标只是 {a}、{b} 两个元素，但候选上界来自整个幂集环境。若只在目标里找，双方都不罩住对方，会误以为无上界；界允许在目标集合之外。'],['上界是一批合格候选','凡包含 a 与 b 的环境集合都合格，所以 {a,b} 和 {a,b,c} 都在上界名单里。成为上界只说明资格通过，不保证已经最优，还要比较这些上界本身。'],['最低要对所有上界成立','{a,b} 包含于每一个上界，因而是最小上界。若某偏序有两个互不可比的极小上界，却没有小于二者的合格者，就没有最小上界；不能任选一个极小当确界。']],'上界与确界是否存在取决于环境；“最低”指偏序最小，不是图纸上画的位置最低。'),
    'dm-function-types': D('每个输入必须一条路，再查撞车和漏人','先判断是否为函数，再区分单射与满射。','给三位同学各分配一个座位，才构成从同学到座位的函数：不能有人没分配，也不能同一个人同时被指定两个不同座位。之后再问座位是否撞车、有没有空着。没人撞座是单射，没有空座是满射，两者都成立才是一一对应。先检查函数资格，再谈这些附加性质。',[['函数','定义域每个输入都恰有一个输出，输出在指定陪域中。','每人分一个指定座位。'],['单射','不同输入不会对应同一输出。','不同人不撞座。'],['满射 / 双射','陪域每个输出都有来源叫满射；兼具单射与满射叫双射。','每座有人且没有撞座。']],'flow',[['逐个输入检查','人人恰好一个座位'],['检查是否撞车','不同人不占同一座'],['检查是否漏输出','指定座位每个都有人']],'座位为数学分配，先不加入现实不能共坐的限制；撞车用于检查单射。',[['函数先要求每个输入有唯一去向','对每位同学都检查，没人漏分配，也没人分到两个不同输出。多个同学分到同一个座位仍符合函数定义，只是可能不符合单射，别把两层条件混在一起。'],['单射关心输入会不会撞在一起','找两个不同同学是否去了同一个输出；找到就否定单射。只有一个人输入而大量座位空着，也可能是单射，因为它从不要求覆盖所有座位。'],['满射使用题给的整个陪域','每个规定座位至少有一个人指向才满射。陪域改变会改变满射判断，即使原有箭头都没动；既无碰撞又无遗漏的函数才是双射。']],'函数的定义域与陪域是题意的一部分，不能为凑满射而偷偷删掉没被用到的输出。'),
    'dm-function-composition-inverse': D('送出去看去向，倒着查不一定只有一个人','区分复合、像、原像与真正的逆函数。','同学先被分到小组，小组再被分到教室，两次分配接起来，就知道每人最终在哪间教室。若反查“这间教室有哪些人”，可能找到许多人，这是原像集合，不要求存在逆函数。只有每个输出恰有一个输入时，才能把反向分配也当成函数。',[['复合函数 g∘f','先按 f 到中间对象，再按 g 到最后对象。','同学→小组→教室。'],['像','一批输入实际到达的输出集合。','几位同学最后使用哪些教室。'],['原像','所有会到达指定输出集合的输入。','哪怕无逆函数也能查某教室所有同学。'],['逆函数','反方向也为函数且可撤回原对应的规则。','需原函数在所定域陪域间双射。']],'flow',[['第一步分组','甲→一组，乙→一组'],['第二步分教室','一组→101 教室'],['反查 101 来源','原像里可同时有甲乙']],'箭头复合按“先 f 后 g”；原像是集合查询，不是数值倒数。',[['中间类型要对得上','f 的输出是小组，g 的输入也必须接受这些小组，才接得起来。复合时先 f 再 g，不能只看两个字母都像函数就不核查范围，也不能随意调换先后。'],['正向与反向查询都可处理集合','像把一批输入送出去再去重；原像则收集所有输出落在目标集合里的输入。甲乙都到101，反查自然得 {甲,乙}，不会因为结果不唯一就让原像不存在。'],['逆函数多要求唯一返回','若101被两个输入命中，反向不能选出唯一原输入，因此原像存在而逆函数未必存在。只有原函数为双射，才可在给定两边建立真正的逐个逆向撤回。']],'上标 −1 用于原像时不预设逆函数存在；须结合它作用于对象还是集合以及教材记号判断。'),
    'dm-finite-cardinality': D('左右一一牵手，就知道是不是一样多','用配对而不是对象外观判断数量。','左边三张卡 A、B、C，右边三个杯子 1、2、3。若每张卡各配一个杯子，不撞也不漏，就能说两边同样多，不必它们长得相似。若只保证不撞，右边可能还有空杯。计数函数、单射或子集时，区别正是每次选择允许重复、要求覆盖还是仅作取舍。',[['基数 |A|','集合成员数量的表示。','|{A,B,C}|＝3。'],['双射计数','建立无碰撞且无遗漏的对应，证明两集合一样多。','三卡三杯逐一配好。'],['函数计数','每个输入可独立选陪域成员，有限情况下为 mⁿ。','n张卡各选m杯，允许多卡同杯。']],'compare',[['无碰撞且无遗漏','双射，有限数量相等'],['只有无碰撞','单射，右边可能剩余'],['任意分配唯一去向','函数，可有重复输出']],'n 为定义域大小、m 为陪域大小；不同条件对应不同计数公式。',[['先辨识要数哪类安排','若每张卡独立选一个杯子，可重复，就是函数；若不许撞，后续可选数量会减少；若每个对象只选不选，那是子集。别见到两个集合就套同一个乘方。'],['配对解释数量相等','给出双射即每个左边成员对应唯一右边，右边也恰被对应一次，所以没有一边多出来。写清具体规则，比只声称“看起来一样多”更能审核。'],['有限条件带来额外结论','有限且两边同样多时，单射便自动满射，否则右边多出空位会与数量冲突；无限集合不沿用这个推断。先写有限条件，才能正确使用计数直觉。']],'0 个元素等边界要与教材的空函数、乘方约定一致；无限情形不能直接套有限抽屉结论。'),
    'dm-infinite-cardinality': D('无限名单还能分成列得完和列不完吗？','把可数理解成能按自然数编号，而不是有限。','整数有正有负，看似比自然数多一倍，却可列成 0、1、−1、2、−2……，每个整数终会有位置。可数不是说最后会数完，而是能安排成不会漏掉对象的编号名单。实数的无限小数串又更复杂，任何声称列全的名单都能用对角线方式造出一个漏项。',[['可数无限','能与自然数一一对应的无限集合。','整数按正负交错列出。'],['列举规则','保证每个对象在有限序号处出现的安排。','先按绝对值再分正负。'],['不可数','不存在把全体成员按自然数逐一编号的双射。','实数不能靠一份无限名单列全。']],'flow',[['排列整数名单','0,1,−1,2,−2,…'],['每个整数有编号','给定整数终能找到'],['小数串反例思路','逐行改第 n 位造漏项']],'十进制对角构造应避开双重表示问题，可只选 1、2 等数字来改位。',[['可数不是有限结束','自然数名单没有最后一项，但每个指定成员都应在某个有限位置出现。整数的交错排列保证了这一点；如果先列完全部正数再列负数，负数永远等不到，不是合格列法。'],['有理数要有系统地扫表','把分子分母排成二维表，沿对角线依次走，并去掉重复表示，可让每个有理数最终入列。不是说二维天然比一维多，而是要给出不漏的实际枚举方法。'],['任意小数名单都能造出漏项','设有人列出无限小数，第 n 行取第 n 位，改成与它不同的安全数字，得到新串。它与第 n 行至少在第 n 位不同，因此不在任何一行；这是针对所有可能名单的反证思路。']],'有限长度串的全体与所有无限串不同；小数表示不唯一会干扰朴素改位，证明时需选择避开该歧义的数字。')
  });
})();
